(()=>{
const nav=document.querySelector('.navigation');
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>nav.open=false));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog[open]')){nav.open=false;nav.querySelector('summary').focus()}});
const magic=document.querySelector('.magic');
magic.addEventListener('click',()=>{const enabled=document.querySelector('.biography').classList.toggle('magic-on');magic.setAttribute('aria-pressed',String(enabled));magic.textContent=enabled?'A little less magic':'Tap to see some magic'});
if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver' in window){
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});
document.querySelectorAll('.project-panel,.quote,.section-intro').forEach(e=>{e.classList.add('reveal');observer.observe(e)});
document.documentElement.classList.add('js-motion');
}
})();

(()=>{const projects=[{"id": "bizinc", "name": "Bizinc", "category": "Marketplace & booking", "role": "Product Designer \u2192 UI/UX Manager", "date": "Apr 2024 \u2014 May 2026", "image": "bizinc", "original": "bizinc-home.jpg", "url": "https://www.bizinc.io", "label": "Visit Bizinc", "intro": "Helping people discover local businesses and book services, while giving business owners a clearer way to manage and grow.", "items": ["Mapped customer and business-owner journeys, from signup to discovery and booking.", "Designed marketplace, business profiles, bookings and operator dashboards.", "Built a shared component library and organised design files for developer handoff."], "scope": "Two-sided marketplace \u00b7 Booking journeys \u00b7 Design system", "result": "Company-reported results during the redesign period included 45% higher dashboard activation and 23% more customers. These are aggregate business figures, not isolated measures of my design contribution."}, {"id": "vista-itss", "name": "Vista Digital Banking", "category": "Banking & fintech", "role": "UI/UX Designer & Front-End Developer \u00b7 ITSS", "date": "May 2022 \u2014 Apr 2024", "image": "vista", "original": "vista-devices.jpg", "url": "https://vistabankgroup.com/", "label": "Visit Vista Bank", "intro": "Making retail and corporate banking easier to navigate across four West African markets.", "items": ["Designed onboarding, identity verification, account dashboards and transfer flows.", "Worked through corporate approval mandates, payments and secure messaging.", "Created reusable patterns for English and French experiences, and supported HTML/CSS implementation reviews."], "scope": "4 markets \u00b7 Retail & corporate banking \u00b7 2 languages", "result": "Recognised with ITSS\u2019s Outstanding Intern of the Year award for work associated with the Vista programme."}, {"id": "kremor-ai", "name": "Kremor AI", "category": "AI & commerce", "role": "UI/UX Designer \u00b7 Design & Research Lead", "date": "Jun 2024 \u2014 Jul 2026 \u00b7 Part-time contract", "image": "kremor", "original": "kremor-hero.jpg", "url": "https://kremor-ai-clone.vercel.app/", "label": "Open project demo", "intro": "Connecting AI-assisted African fashion creation with shopping and the workshop operations needed to make it real.", "items": ["Designed the customer storefront, AI creative workspace and operations dashboard.", "Added prompt guidance, quick actions and history to help people get started with AI creation.", "Mapped orders, measurements, artisan workflows and permissions across five staff roles."], "scope": "3 product surfaces \u00b7 5 staff roles \u00b7 Shared design system", "result": "Delivered connected experiences and developer-ready design handoff across the storefront, creative workspace and admin tools. The linked site is the project demo from my existing portfolio."}];projects.push(...[{"id": "pay4me", "content": "<p class=\"drawer-kicker\">Live product</p><h2 id=\"preview-title\">Radius</h2><p class=\"drawer-intro\">Paying tuition, SEVIS and visa fees across borders \u2014 for students whose admission depends on the transfer clearing.</p><dl class=\"drawer-facts\"><div><dt>MY ROLE</dt><dd>Product designer</dd></div><div><dt>WHEN</dt><dd>2025</dd></div><div><dt>FOCUS</dt><dd>High-stakes cross-border payments, sponsored payments, trust before install</dd></div></dl><img class=\"archive-cover\" src=\"/projects/pay4me-hero.jpg\" alt=\"Radius interface overview\" width=\"2000\" height=\"1330\"><div class=\"archive-story\"><section class=\"case-section\"><h2>The short version</h2><div><p>Radius \u2014 the product I designed as Pay4Me App, since rebranded \u2014 is a cross-border payments platform for international students and immigrants, covering tuition, SEVIS, I-20, visa and credential-evaluation fees paid to institutions and government agencies abroad. I designed the mobile product and the marketing site that has to earn a stranger&#x27;s trust before they will download it.</p></div></section><section class=\"case-section\"><h2>What I owned</h2><div><p>I designed the mobile experience for international students and families making high-stakes cross-border payments \u2014 payment journeys, sponsored payments where the payer and the beneficiary are different people, verification and tier status, transaction tracking, currency visibility and support. I designed the marketing site that has to earn a stranger&#x27;s trust before the app is installed, and worked on making payment language plainer and more credible at the moment someone commits a family&#x27;s savings.</p></div></section><div class=\"metric-row\"><div><strong>100K+</strong><p>International students using Radius</p><small>Company traction</small></div><div><strong>1,500+</strong><p>Five-star reviews for speed and reliability</p><small>Company traction</small></div><div><strong>6h</strong><p>Average payment processing time</p><small>Company traction</small></div></div><section class=\"case-section\"><h2>The challenge</h2><div><p>For an international student, a payment is not a transaction \u2014 it is a deadline. Miss a SEVIS fee and the visa appointment goes with it; miss a tuition instalment and the admission can lapse. Yet the money usually has to travel the hardest possible route: from a family in one currency, through a banking system with limited access to dollars, to a university that only recognises payments arriving in a particular form. Traditional wires are slow, expensive and opaque, and the person waiting has no way to see where their money is. Two design problems follow from that. The sums are often a family&#x27;s savings, sent by someone who has never heard of the company \u2014 so credibility has to be established before the app is even installed. And the person paying is frequently not the person benefiting, which breaks the assumption almost every payment app is built on.</p></div></section><section class=\"case-section\"><h2>The tricky part</h2><div><p>The product has to earn trust in the wrong order. Someone judges a payments company on a laptop, at the point where they know least and have most at stake, then pays on a phone \u2014 which forced the credibility work into the marketing site, where reassurance can arrive before the decision, rather than into the app, where it would arrive too late to matter. The second difficulty is structural rather than emotional: the account holder is often a parent or relative and the beneficiary is the student, which breaks the assumption almost every payment app is built on. Sponsored payment had to become a first-class transfer type rather than a personal wallet bent into a shape it was never designed for.</p></div></section><section class=\"case-section\"><h2>Research &amp; learning</h2><div><p>Product-design-led, grounded in the category&#x27;s real deadlines</p><p>Why a payment in this category is a deadline rather than a transaction, and where credibility has to be established relative to where the payment happens.</p><p>The person paying is frequently not the person benefiting, and judgement about the company happens on a desktop before the app is ever installed.</p><p>Sponsored payment became a first-class payment type rather than a personal wallet bent into shape, and the credibility work moved into the marketing site with a QR handoff to the phone.</p><p>Completion behaviour for first-time sponsors, which needs instrumentation rather than inference.</p></div></section><section class=\"case-section\"><h2>Design decisions</h2><div><ol><li>Designed for the sponsor, not just the account holder. Parents and relatives fund most of these payments, so the product treats sponsored payment as a first-class type alongside seamless and cross-border \u2014 rather than bending a personal wallet into a use case it was never shaped for.</li><li>Made recipients people instead of account numbers. Recent transfers appear as faces and first names, and the search field asks you to find a friend or family member to send money to \u2014 matching how these transfers are actually described out loud, and removing a common source of costly typos.</li><li>Put currency where the money is. The balance carries its own currency switcher rather than burying conversion in a settings screen, because holding and thinking in more than one currency is the normal state for this user, not an edge case.</li><li>Surfaced verification status as identity. The account tier sits beside the user&#x27;s name and verified badge, because in this category tier determines transfer limits \u2014 so what would otherwise be buried compliance state becomes information the user needs before starting a large payment.</li><li>Named the real jobs rather than generic ones. The site speaks in SEVIS, WES, I-20, visa applications and credential evaluations, not payments and services \u2014 using the exact vocabulary of the immigration journey, which both signals competence and lets people recognise their situation instantly.</li><li>Built the marketing site as trust architecture, layered by kind of doubt: payment processors and named universities answer is this real, a world map answers do you work where I am, video testimonials from students answer has this worked for someone like me, and an FAQ given two full columns answers the rest.</li><li>Bridged desktop research to mobile action with a QR code. People investigate a payments company on a laptop but pay on a phone, so the site closes that gap directly rather than asking them to search an app store later.</li><li>Kept everyday utility in the app between the big moments. Airtime top-up and bill payment give people a reason to open it in the months between tuition instalments, so the product is already familiar when the payment that matters arrives.</li><li>Made support a destination, not a dead end. It sits in the bottom navigation as one of four primary tabs \u2014 appropriate for high-value, high-anxiety transfers where being unable to reach a human is itself the failure.</li></ol></div></section><div class=\"case-gallery\"><figure><img src=\"/projects/pay4me-features.jpg\" alt=\"The product named in the vocabulary of the journey: tuition and school fees paid to named institutions, and a separate block for SEVIS, WES, visa and credential-evaluation payments\" loading=\"lazy\" width=\"2000\" height=\"1330\"><figcaption>The product named in the vocabulary of the journey: tuition and school fees paid to named institutions, and a separate block for SEVIS, WES, visa and credential-evaluation payments</figcaption></figure><figure><img src=\"/projects/pay4me-map.jpg\" alt=\"Trust built through evidence \u2014 a world map of the countries served, with video testimonials from students rather than written quotes\" loading=\"lazy\" width=\"2000\" height=\"1330\"><figcaption>Trust built through evidence \u2014 a world map of the countries served, with video testimonials from students rather than written quotes</figcaption></figure><figure><img src=\"/projects/pay4me-qr.jpg\" alt=\"The FAQ handoff: a QR code that carries the visitor from desktop research to the app on their phone, where the payment actually happens\" loading=\"lazy\" width=\"2000\" height=\"1330\"><figcaption>The FAQ handoff: a QR code that carries the visitor from desktop research to the app on their phone, where the payment actually happens</figcaption></figure><figure><img src=\"/projects/pay4me-download.jpg\" alt=\"Download section pairing the app-store routes with the in-app home screen, so the product is visible before installation\" loading=\"lazy\" width=\"2000\" height=\"1330\"><figcaption>Download section pairing the app-store routes with the in-app home screen, so the product is visible before installation</figcaption></figure></div><section class=\"case-section\"><h2>What changed</h2><div><p>A payments product shaped around the real unit of work \u2014 a family funding someone else&#x27;s education across a border, against a deadline. Sponsored payments are designed for rather than tolerated, verification and currency are treated as everyday context instead of settings, the interface speaks the immigration journey&#x27;s own vocabulary, and the site does the credibility work before the download rather than after it.</p></div></section><section class=\"case-section\"><h2>The evidence</h2><div><p>Payment types are modelled around a sponsor rather than a single account holder, so the person paying and the person benefiting are both first-class rather than one being bent into the other&#x27;s shape. Verification tier and currency sit in the interface as everyday context instead of buried settings. The marketing site is layered by kind of doubt \u2014 payment processors and named institutions, a coverage map, video testimonials from students, then a two-column FAQ \u2014 and a QR code closes the desktop-to-mobile gap at the exact point the decision is made.</p></div></section><section class=\"case-section\"><h2>What I\u2019d test next</h2><div><p>Two numbers would tell me whether this works: the completion rate of a first sponsored payment by someone who has never used the app, and the drop-off between the marketing site and the app install. I would also usability-test the fee and timing disclosure with families sending money abroad for the first time, since that is the moment trust is either earned or lost.</p></div></section><p style=\"margin-top:40px\"><a class=\"button primary\" href=\"https://withradius.com/\" target=\"_blank\" rel=\"noopener\">View Radius \u2197</a></p></div>"}, {"id": "chalant-ai", "content": "<p class=\"drawer-kicker\">Prototype</p><h2 id=\"preview-title\">Chalant AI</h2><p class=\"drawer-intro\">Teaching people to manage AI by giving them a team to manage \u2014 with the judgement built in, not lectured about.</p><dl class=\"drawer-facts\"><div><dt>MY ROLE</dt><dd>Lead product designer</dd></div><div><dt>WHEN</dt><dd>2025</dd></div><div><dt>FOCUS</dt><dd>Calibrated trust, human review checkpoints, dual-role product design</dd></div></dl><img class=\"archive-cover\" src=\"/projects/chalant-tasks.jpg\" alt=\"Chalant AI interface overview\" width=\"1800\" height=\"1295\"><div class=\"archive-story\"><section class=\"case-section\"><h2>The short version</h2><div><p>Chalant AI is a learning platform for people who need to work with AI rather than merely read about it. Alongside courses, live sessions and voice learning sits the AI Manager Path \u2014 a simulated workspace where learners run a team of AI agents, assign real tasks, review the output and answer for the quality. I led end-to-end product design across the learner and admin experiences.</p></div></section><section class=\"case-section\"><h2>What I owned</h2><div><p>I led the end-to-end product design for both sides of the platform: the learner&#x27;s AI Manager Path with its team of five agents, the review queue and confidence system, the SOP library, task management and export centre, and the administrator&#x27;s course builder, analytics and revenue surfaces. I designed the progression system and the single design system that keeps learner and operator inside one product rather than two.</p></div></section><div class=\"metric-row\"><div><strong>5</strong><p>AI agents a learner manages, each with role, status and workload</p><small>Project scope</small></div><div><strong>2</strong><p>Roles in one system \u2014 learner and administrator</p><small>Project scope</small></div><div><strong>4</strong><p>Export formats \u2014 PDF, Excel, PowerPoint and JSON</p><small>Project scope</small></div></div><section class=\"case-section\"><h2>The challenge</h2><div><p>The skill people actually need around AI is not prompting \u2014 it is management: deciding what to delegate, judging whether the result is good enough, and knowing when a confident-sounding output should be rejected. That judgement cannot be transferred by watching a video, because the failure mode being trained against is precisely the one a passive learner exhibits: accepting plausible work without checking it. So the platform had to teach through practice with consequences, while remaining a product an administrator could run as a business \u2014 which meant one system serving a learner who wants to progress and an operator who needs to see engagement, revenue and where courses are failing.</p></div></section><section class=\"case-section\"><h2>The tricky part</h2><div><p>Quick Approve is the whole tension in a single control. The product exists to teach people not to accept plausible AI output without checking it, so a shortcut that lets them do exactly that is the obvious thing to delete. Deleting it makes the exercise dishonest: in real work the shortcut always exists, and a tool that forbids it trains compliance rather than judgement. Keeping it meant accepting that learners can take the easy path, and designing the surrounding signals \u2014 confidence score, estimated review time, SOP compliance \u2014 so that taking it is a decision they can watch themselves make. The same tension runs through the progression system: XP and streaks sustain a path measured in weeks, but rewarding throughput inside a product about careful review would teach precisely the wrong habit, which is why progression sits in the sidebar as ambient context instead of driving the work.</p></div></section><section class=\"case-section\"><h2>Research &amp; learning</h2><div><p>Exploratory, product-design-led</p><p>What skill actually needs teaching \u2014 the finding was that it is management and judgement, not prompt writing.</p><p>The failure mode being trained against is accepting plausible output without checking it, which is exactly what a passive learner does.</p><p>The lesson became a workspace with consequences rather than a module, and Quick Approve was deliberately kept so the trade-off stays real.</p><p>Whether the platform actually improves calibrated trust \u2014 the central claim, and the one that most needs measuring.</p></div></section><section class=\"case-section\"><h2>Design decisions</h2><div><ol><li>Made the lesson a workspace. The AI Manager Path drops the learner into a team of five agents with roles, live status and current tasks \u2014 so the unit of learning is a decision made under realistic conditions rather than a module completed.</li><li>Exposed the numbers a manager would actually use. Every agent card carries accuracy, task volume, average turnaround and progress, so judging performance means reading evidence instead of trusting a vibe.</li><li>Designed the Review Queue as the heart of the product. Each submission states a confidence score, an estimated review time and whether it passed SOP compliance \u2014 three signals that together teach calibrated trust rather than blanket acceptance or blanket suspicion.</li><li>Kept Quick Approve next to full Review, deliberately. The shortcut has to exist for the trade-off to be real; a tool that forbids it teaches compliance, not judgement.</li><li>Anchored quality in written standards. The SOP Library holds versioned procedures with ownership, compliance scoring and critical alerts, and any SOP can be linked to a task \u2014 so good output means measured against something, not merely looks right.</li><li>Made the human checkpoint structural. Needs Review is its own column on the task board rather than a flag, so work cannot reach Done without passing through a person.</li><li>Gave practice an artefact. The Export Center sends reports, analytics, decks and task data out as PDF, Excel, PowerPoint and JSON, so a training exercise ends in something the learner can actually use at work.</li><li>Tuned progression for a long path. XP, levels, streaks, badges and rank sustain momentum across weeks of practice, and sit in the sidebar as ambient context rather than interrupting the work.</li><li>Built one product for two roles. A role switch reveals the operator&#x27;s surfaces \u2014 course builder, path analytics, plan and revenue \u2014 so learner and admin share a single design system instead of splitting into two disconnected apps.</li><li>Made analytics end in a decision. Each AI insight names the course and module, quantifies the problem, proposes a specific action and states its own confidence \u2014 modelling, in the admin product, exactly the calibrated-trust behaviour the learner product is teaching.</li></ol></div></section><div class=\"case-gallery\"><figure><img src=\"/projects/chalant-workspace.jpg\" alt=\"The AI Agent Workspace: five agents with role, live status, current task and progress, alongside accuracy and volume figures \u2014 the learner reads their team the way a manager reads a standup\" loading=\"lazy\" width=\"1400\" height=\"1647\"><figcaption>The AI Agent Workspace: five agents with role, live status, current task and progress, alongside accuracy and volume figures \u2014 the learner reads their team the way a manager reads a standup</figcaption></figure><figure><img src=\"/projects/chalant-review.jpg\" alt=\"The Review Queue states each output&#x27;s confidence score, an estimated review time and whether it passed SOP compliance \u2014 Quick Approve sits beside a full Review rather than replacing it\" loading=\"lazy\" width=\"1800\" height=\"1273\"><figcaption>The Review Queue states each output&#x27;s confidence score, an estimated review time and whether it passed SOP compliance \u2014 Quick Approve sits beside a full Review rather than replacing it</figcaption></figure><figure><img src=\"/projects/chalant-sop.jpg\" alt=\"The SOP Library: versioned standard operating procedures with compliance rings, a critical alert surfaced at the top, and each SOP linkable directly to a task\" loading=\"lazy\" width=\"1800\" height=\"1273\"><figcaption>The SOP Library: versioned standard operating procedures with compliance rings, a critical alert surfaced at the top, and each SOP linkable directly to a task</figcaption></figure><figure><img src=\"/projects/chalant-export.jpg\" alt=\"The Export Center turns practice into artefacts \u2014 agent reports, analytics, decks and task data leaving in PDF, Excel, PowerPoint and JSON\" loading=\"lazy\" width=\"1800\" height=\"1273\"><figcaption>The Export Center turns practice into artefacts \u2014 agent reports, analytics, decks and task data leaving in PDF, Excel, PowerPoint and JSON</figcaption></figure><figure><img src=\"/projects/chalant-analytics.jpg\" alt=\"Admin analytics where each AI insight names the course and module, quantifies the drop-off, recommends an action and states its own confidence\" loading=\"lazy\" width=\"1800\" height=\"1273\"><figcaption>Admin analytics where each AI insight names the course and module, quantifies the drop-off, recommends an action and states its own confidence</figcaption></figure></div><section class=\"case-section\"><h2>What changed</h2><div><p>A learning product where the curriculum is the work itself: agents to delegate to, confidence scores and SOPs to judge against, a review step that cannot be skipped structurally, and exports that turn practice into deliverables. Learner and operator share one design system, and the same principle runs through both \u2014 surface the evidence, name the confidence, and leave the judgement with the person.</p></div></section><section class=\"case-section\"><h2>The evidence</h2><div><p>The human checkpoint is structural rather than advisory: Needs Review is its own column, so work cannot reach Done without passing through a person. Quality is anchored to versioned SOPs rather than to taste, learner and operator share one design system instead of splitting into two disconnected apps, and the Export Centre turns a training exercise into artefacts a learner can actually use at work.</p></div></section><section class=\"case-section\"><h2>What I\u2019d test next</h2><div><p>The obvious study is whether a learner&#x27;s approval accuracy improves across sessions \u2014 comparing what they approve early against what they approve after working through the SOP library \u2014 and whether Quick Approve use falls as judgement develops. That would turn the product&#x27;s central claim into something measured rather than argued.</p></div></section><p style=\"margin-top:40px\"><a class=\"button primary\" href=\"https://chalantwork.com/\" target=\"_blank\" rel=\"noopener\">View chalantwork.com \u2197</a></p></div>"}, {"id": "arete", "content": "<p class=\"drawer-kicker\">Concept exploration</p><h2 id=\"preview-title\">Arete</h2><p class=\"drawer-intro\">Care that stays connected \u2014 from needing a doctor to actually holding the medicine.</p><dl class=\"drawer-facts\"><div><dt>MY ROLE</dt><dd>End-to-end product designer</dd></div><div><dt>WHEN</dt><dd>2026</dd></div><div><dt>FOCUS</dt><dd>Connected care journeys, coverage clarity, accessibility and low connectivity</dd></div></dl><img class=\"archive-cover\" src=\"/projects/arete-cover.jpg\" alt=\"Arete interface overview\" width=\"2000\" height=\"1500\"><div class=\"archive-story\"><section class=\"case-section\"><h2>The short version</h2><div><p>Arete is a connected healthcare ecosystem rather than a doctor-booking app. It brings care discovery, consultations, medical records, insurance coverage, prescriptions and pharmacy fulfilment into one experience, designed for accessibility, localisation and low-connectivity environments. I was the end-to-end product designer, covering UX, UX writing, UI and prototyping across the patient, provider, HMO and pharmacy surfaces.</p></div></section><section class=\"case-section\"><h2>What I owned</h2><div><p>I designed the connected healthcare ecosystem end to end \u2014 UX strategy, information architecture, user flows, UX writing, UI design, the design system and interactive prototyping. I designed the seven-step care journey, the onboarding and identity flows, the HMO coverage module, prescription and pharmacy fulfilment, and the status and edge-case system that holds the whole thing together.</p></div></section><div class=\"metric-row\"><div><strong>7</strong><p>Steps designed, from needing care to continuing it</p><small>Project scope</small></div><div><strong>6</strong><p>Actors the requirements covered</p><small>Project scope \u00b7 Patients, doctors, nurses, community health workers, HMO teams, pharmacies and administrators</small></div><div><strong>4</strong><p>Surfaces \u2014 patient, provider, HMO and pharmacy</p><small>Project scope</small></div></div><section class=\"case-section\"><h2>The challenge</h2><div><p>Getting medical advice is only one part of a patient&#x27;s journey. Someone also has to understand whether care is covered, find a provider their plan will accept, receive a prescription, locate the medication and keep taking it afterwards \u2014 and each of those steps usually lives in a different place, run by a different organisation. The product had to bring those disconnected steps into one understandable experience without hiding the detail that clinicians and insurers require, and it had to do it for patients, doctors and nurses, community health workers, HMO teams, pharmacies and administrators at once.</p></div></section><section class=\"case-section\"><h2>The tricky part</h2><div><p>The four things a patient needs are run by different organisations with different systems and different obligations, so presenting them as one journey is a claim the underlying services do not make on their own \u2014 and the risk is a product that feels seamless right up to the moment it hands you off and stops helping. Coverage is where that hurts most: eligibility language has to be plain enough to act on and precise enough not to promise something an insurer will later refuse, and getting it wrong in either direction costs the patient. The context tightened it further. Multilingual users, low-connectivity environments and high-stakes tasks ruled out clever interactions and icon-only affordances, and writing for people who are unwell ruled out most of the reassuring tone a product designer reaches for by default \u2014 reassurance that overstates is worse than silence.</p></div></section><section class=\"case-section\"><h2>Research &amp; learning</h2><div><p>Exploratory, product-design-led</p><p>Where a telemedicine product stops helping \u2014 the finding was that most stop at the booking, while the patient&#x27;s problem continues into coverage, prescription and fulfilment.</p><p>Coverage is the point of highest risk: language has to be plain enough to act on and precise enough not to promise what an insurer will later refuse.</p><p>The journey was designed past the consultation, and Skip for Now was kept throughout so an uninsured patient is never blocked from reaching a doctor.</p><p>Whether patients read a coverage state as actionable \u2014 untested, and the most consequential unknown in the product.</p></div></section><section class=\"case-section\"><h2>Design decisions</h2><div><ol><li>Framed the design around how information and actions move between roles rather than how individual screens look, because the requirements covered patients, doctors and nurses, community health workers, HMO teams, pharmacies and administrators sharing one product.</li><li>Resolved the requirements into four principles that could settle arguments later \u2014 simple first, accessible, localised, transparent \u2014 and held decisions against them rather than against taste.</li><li>Designed the journey past the booking, which is where most telemedicine products stop: need care, find provider, consult, check coverage, get prescription, find pharmacy, continue care. Each step is a place the journey can fail, so each got designed rather than assumed.</li><li>Broke registration into progressive steps with visible progress, explicit verification language and real recovery paths, because the first interaction with a health product is where trust is either established or lost.</li><li>Put coverage before commitment. The HMO module verifies membership, states what the plan covers and its limits, and surfaces eligible providers before a patient chooses care \u2014 and Skip for Now stays available throughout, so an uninsured patient is never blocked from reaching a doctor.</li><li>Treated a prescription as unfinished until the medicine is in hand: nearby stock, pickup or delivery, fulfilment confirmation, reminders, and explicit out-of-stock and alternative-medication paths.</li><li>Designed the non-happy paths as core UX rather than edge cases \u2014 OTP errors, verification loading, HMO approval states, plan removal with reason capture, availability signals and confirmations \u2014 and gave status its own vocabulary so error, pending, unavailable and success are never ambiguous.</li><li>Paired every action with legible text instead of icon-only interactions, and kept language and cultural context in the copy, so the interface holds up for multilingual users on poor connections.</li><li>Built the system underneath \u2014 a calm healthcare green with high-contrast neutrals, Noto Sans at defined sizes, and reusable field, card, alert, button and status patterns \u2014 so a high-stakes interaction feels the same whether it sits in the patient, insurance or pharmacy journey.</li></ol></div></section><div class=\"case-gallery\"><figure><img src=\"/projects/arete-overview.jpg\" alt=\"The project framing: an end-to-end product design role across the patient, provider, HMO and pharmacy surfaces, focused on access, trust and continuity\" loading=\"lazy\" width=\"2000\" height=\"873\"><figcaption>The project framing: an end-to-end product design role across the patient, provider, HMO and pharmacy surfaces, focused on access, trust and continuity</figcaption></figure><figure><img src=\"/projects/arete-challenge.jpg\" alt=\"The problem stated as four jobs rather than one: reaching trusted care, understanding what coverage pays for, connecting a consultation to medication fulfilment, and continuing treatment afterwards\" loading=\"lazy\" width=\"2000\" height=\"951\"><figcaption>The problem stated as four jobs rather than one: reaching trusted care, understanding what coverage pays for, connecting a consultation to medication fulfilment, and continuing treatment afterwards</figcaption></figure><figure><img src=\"/projects/arete-ecosystem.jpg\" alt=\"The actors the requirements had to serve \u2014 patient, doctor and nurse, community health worker, HMO, pharmacy and administrator \u2014 mapped around the product, because the design problem was how information and actions move between roles rather than how any single screen looks\" loading=\"lazy\" width=\"2000\" height=\"951\"><figcaption>The actors the requirements had to serve \u2014 patient, doctor and nurse, community health worker, HMO, pharmacy and administrator \u2014 mapped around the product, because the design problem was how information and actions move between roles rather than how any single screen looks</figcaption></figure><figure><img src=\"/projects/arete-principles.jpg\" alt=\"The four principles the requirements resolved into: simple first in high-stakes tasks, accessible through explicit rather than icon-only actions, localised for language and cultural context, and transparent about eligibility, status and next steps\" loading=\"lazy\" width=\"2000\" height=\"951\"><figcaption>The four principles the requirements resolved into: simple first in high-stakes tasks, accessible through explicit rather than icon-only actions, localised for language and cultural context, and transparent about eligibility, status and next steps</figcaption></figure><figure><img src=\"/projects/arete-onboarding.jpg\" alt=\"Onboarding as a structured entry into a sensitive product \u2014 account creation, OTP verification and profile setup broken into steps with progress shown, explicit verification language and recovery paths, rather than one long form\" loading=\"lazy\" width=\"2000\" height=\"1239\"><figcaption>Onboarding as a structured entry into a sensitive product \u2014 account creation, OTP verification and profile setup broken into steps with progress shown, explicit verification language and recovery paths, rather than one long form</figcaption></figure><figure><img src=\"/projects/arete-journey.jpg\" alt=\"The flagship journey end to end: need care, find provider, consult, check coverage, get prescription, find pharmacy, continue care \u2014 with the screens that carry it, including symptom capture, family-member selection and a profile review before a practitioner sees it\" loading=\"lazy\" width=\"2000\" height=\"1239\"><figcaption>The flagship journey end to end: need care, find provider, consult, check coverage, get prescription, find pharmacy, continue care \u2014 with the screens that carry it, including symptom capture, family-member selection and a profile review before a practitioner sees it</figcaption></figure><figure><img src=\"/projects/arete-hmo.jpg\" alt=\"The HMO module: membership verification with its own loading state, what the plan covers and its limits, eligible providers, and the plan card showing balance and validity \u2014 with Skip for Now kept available so an uninsured patient is never blocked\" loading=\"lazy\" width=\"2000\" height=\"1239\"><figcaption>The HMO module: membership verification with its own loading state, what the plan covers and its limits, eligible providers, and the plan card showing balance and validity \u2014 with Skip for Now kept available so an uninsured patient is never blocked</figcaption></figure><figure><img src=\"/projects/arete-pharmacy.jpg\" alt=\"Pharmacy fulfilment as a chain rather than a hand-off: prescription, nearby stock on a map, reserve or deliver with pickup and rider options, then medication reminders per drug with dosage, timing and days remaining\" loading=\"lazy\" width=\"2000\" height=\"1704\"><figcaption>Pharmacy fulfilment as a chain rather than a hand-off: prescription, nearby stock on a map, reserve or deliver with pickup and rider options, then medication reminders per drug with dosage, timing and days remaining</figcaption></figure><figure><img src=\"/projects/arete-states.jpg\" alt=\"The non-happy paths designed as first-class: OTP errors, incorrect password, verification loading, plan removal with reason capture and an explicit warning that it cannot be undone, plus the full status vocabulary \u2014 error, loading, pending approval, success, unavailable, confirmation\" loading=\"lazy\" width=\"2000\" height=\"1614\"><figcaption>The non-happy paths designed as first-class: OTP errors, incorrect password, verification loading, plan removal with reason capture and an explicit warning that it cannot be undone, plus the full status vocabulary \u2014 error, loading, pending approval, success, unavailable, confirmation</figcaption></figure><figure><img src=\"/projects/arete-design-system.jpg\" alt=\"The system underneath: a calm healthcare green with high-contrast neutrals, Noto Sans set at four defined sizes, and reusable patterns for fields, cards, alerts, buttons and status feedback so high-stakes interactions stay familiar across patient, insurance and pharmacy journeys\" loading=\"lazy\" width=\"2000\" height=\"1216\"><figcaption>The system underneath: a calm healthcare green with high-contrast neutrals, Noto Sans set at four defined sizes, and reusable patterns for fields, cards, alerts, buttons and status feedback so high-stakes interactions stay familiar across patient, insurance and pharmacy journeys</figcaption></figure><figure><img src=\"/projects/arete-reflection.jpg\" alt=\"The closing reflection from the case study deck \u2014 owning UX strategy, IA, user flows, UX writing, UI, the design system and interactive prototyping, and bringing them into one consistent product experience\" loading=\"lazy\" width=\"2000\" height=\"674\"><figcaption>The closing reflection from the case study deck \u2014 owning UX strategy, IA, user flows, UX writing, UI, the design system and interactive prototyping, and bringing them into one consistent product experience</figcaption></figure><figure><img src=\"/projects/arete-hero.jpg\" alt=\"The project&#x27;s positioning line \u2014 care should feel connected \u2014 over the disciplines the work covered\" loading=\"lazy\" width=\"2000\" height=\"632\"><figcaption>The project&#x27;s positioning line \u2014 care should feel connected \u2014 over the disciplines the work covered</figcaption></figure></div><section class=\"case-section\"><h2>What changed</h2><div><p>A healthcare product designed as a chain rather than a set of features: the patient journey continues past the consultation into coverage, prescription and fulfilment, and the moments where it could break \u2014 an unverified plan, an out-of-stock medicine, a failed OTP, a removed HMO \u2014 are designed states rather than dead ends. One system of colour, type and components holds the patient, provider, HMO and pharmacy surfaces together, and the whole experience is built for legibility, localisation and low connectivity rather than assuming ideal conditions.</p></div></section><section class=\"case-section\"><h2>The evidence</h2><div><p>The seven-step journey is designed end to end rather than stopping at the booking, where most telemedicine products stop. The status vocabulary and edge cases are specified alongside the happy paths, the HMO module keeps Skip for Now available so coverage never blocks access to care, and the design system defines a palette, four type sizes and reusable field, card, alert, button and status patterns across all four surfaces. The full case study is published on Behance.</p></div></section><section class=\"case-section\"><h2>What I\u2019d test next</h2><div><p>Eligibility comprehension is the thing to test first \u2014 whether a patient reads a coverage state as something they can act on rather than a status they have to interpret \u2014 and it needs real patients rather than colleagues. I would then validate the hand-off points with an actual insurer and pharmacy, since the journey&#x27;s credibility rests on partners the design cannot control, and test the low-connectivity assumptions on real networks rather than on a design file.</p></div></section><p style=\"margin-top:40px\"><a class=\"button primary\" href=\"https://www.behance.net/gallery/255070051/Arete-Telemedicine-UXUI-Case-Study\" target=\"_blank\" rel=\"noopener\">View project presentation \u2197</a></p></div>"}, {"id": "shortlet-lagos", "content": "<p class=\"drawer-kicker\">Live product</p><h2 id=\"preview-title\">Shortlet Lagos</h2><p class=\"drawer-intro\">Property discovery, search, filtering and booking inside a reusable responsive design system.</p><dl class=\"drawer-facts\"><div><dt>MY ROLE</dt><dd>Product designer &amp; researcher</dd></div><div><dt>WHEN</dt><dd>2024</dd></div><div><dt>FOCUS</dt><dd>Two audiences, two decision speeds, one portfolio of apartments</dd></div></dl><img class=\"archive-cover\" src=\"/projects/shortlet-laptop.jpg\" alt=\"Shortlet Lagos interface overview\" width=\"2000\" height=\"1178\"><div class=\"archive-story\"><section class=\"case-section\"><h2>The short version</h2><div><p>Shortlet Lagos runs two products against one portfolio of apartments: guests book short stays, and investors buy shares in the same rental properties from \u20a650,000 upward. I owned end-to-end UX/UI design and research across both \u2014 discovery, search, filtering and booking on the guest side, and the property marketplace on the investment side.</p></div></section><section class=\"case-section\"><h2>What I owned</h2><div><p>I owned the end-to-end UX and UI across both sides of the product: guest discovery, search, filtering and booking on mobile, and the fractional investment marketplace on desktop \u2014 property listings, share mechanics and entry pricing. I built the responsive component set both sides share, and designed the brand identity the platform sits inside.</p></div></section><div class=\"metric-row\"><div><strong>2</strong><p>Audiences served by one portfolio \u2014 guests and investors</p><small>Project scope</small></div><div><strong>4</strong><p>Inputs the guest search reduces to \u2014 where, check-in, check-out, who</p><small>Project scope</small></div><div><strong>\u20a650,000</strong><p>Entry point for a fractional property share</p><small>Project scope</small></div></div><section class=\"case-section\"><h2>The challenge</h2><div><p>The same apartment has to read two completely different ways depending on who is looking at it. To a guest it is somewhere to sleep next weekend, judged on photos, location and whether the dates are free \u2014 a decision made in minutes, usually on a phone. To an investor it is an asset, judged on yield, entry price and what happens to the money afterwards \u2014 a decision made slowly, at a desk, and one that carries real risk. Fractional property investment also has a credibility problem before it has a usability one: asking someone to put money into a share of a building they will never hold the keys to means the interface has to make the mechanics obvious rather than exciting. Designing both without letting the marketing energy of the booking side leak into the investment side was the core problem.</p></div></section><section class=\"case-section\"><h2>The tricky part</h2><div><p>The same apartment has to read two ways. A guest decides in minutes, on a phone, on photos, location and whether the dates are free. An investor decides slowly, at a desk, on yield and entry price and what happens to the money afterwards, with real risk attached. The pull throughout was to let the booking side&#x27;s marketing energy carry across into the investment side, because that energy converts \u2014 and that is exactly where it would do damage, since making an investment decision feel effortless is not the same as making it clear. Holding the two apart while keeping them recognisably one company was the constant tension, and it is why the investment side leads with the buying mechanic and the entry price rather than with projected returns.</p></div></section><section class=\"case-section\"><h2>Research &amp; learning</h2><div><p>Product-design-led, with research into how guests shortlist</p><p>Which signals drive trust in a short-let listing, and what an investor needs before a fractional share is comprehensible.</p><p>The two decisions have opposite tolerances \u2014 the energy that converts a booking is the energy that undermines an investment decision.</p><p>The two entry points were kept deliberately separate, and the investment side leads with the buying mechanic and the \u20a650,000 minimum before it discusses return.</p><p>Whether people actually understand what a fractional share is \u2014 comprehension, not conversion, is the right measure here.</p></div></section><section class=\"case-section\"><h2>Design decisions</h2><div><ol><li>Split the product into two entry points rather than one blended homepage, so a guest and an investor are answering different questions from the first screen instead of being sold the wrong one.</li><li>Reduced the guest search to the four things a stay actually turns on \u2014 where, check-in, check-out, who \u2014 and kept them in a single card above the listings, so the whole query is visible and editable in one place on a phone.</li><li>Led the investment side with the mechanic rather than the promise: buy shares in rental properties, share by share, from a stated minimum, so the model is understood before any return is discussed.</li><li>Put the entry price on the surface. Naming the \u20a650,000 minimum up front lets someone rule themselves in or out immediately, instead of discovering the threshold after signing up.</li><li>Kept the property itself central on the investment side \u2014 gallery, valuation and share count together \u2014 so an investment decision is still anchored in a real building rather than an abstract instrument.</li><li>Wrote the value proposition against the objection rather than around it: building wealth through real estate without huge capital or the hassle of tenant management names the two reasons people rule property out.</li><li>Built responsive components in Figma with Auto Layout and variants for listing cards, calendars, forms and property tiles, so the guest and investor surfaces stayed recognisably one company.</li></ol></div></section><div class=\"case-gallery\"><figure><img src=\"/projects/shortlet-invest.jpg\" alt=\"The investment side: shares in high-yield rental properties from \u20a650,000, with the property gallery, valuation and share count shown together \u2014 the same apartment a guest would book, presented as an asset\" loading=\"lazy\" width=\"1900\" height=\"1425\"><figcaption>The investment side: shares in high-yield rental properties from \u20a650,000, with the property gallery, valuation and share count shown together \u2014 the same apartment a guest would book, presented as an asset</figcaption></figure><figure><img src=\"/projects/shortlet-phone.jpg\" alt=\"The guest side on mobile: where, check-in, check-out and who, held in a single search card above the listings \u2014 the four questions a stay actually turns on\" loading=\"lazy\" width=\"1900\" height=\"1267\"><figcaption>The guest side on mobile: where, check-in, check-out and who, held in a single search card above the listings \u2014 the four questions a stay actually turns on</figcaption></figure></div><section class=\"case-section\"><h2>What changed</h2><div><p>One platform serving two audiences with genuinely different decisions to make \u2014 a mobile booking journey reduced to the four questions a stay depends on, and a fractional investment marketplace that leads with its mechanics and its entry price rather than with projected returns. Both sit on a shared responsive component set. The product is live at shortlet-lagos.com.</p></div></section><section class=\"case-section\"><h2>The evidence</h2><div><p>The product is live at shortlet-lagos.com. The guest search is reduced to the four inputs a stay actually depends on, and the investment side leads with the buying mechanic and the minimum entry price before it discusses return \u2014 so someone can rule themselves in or out before they sign up rather than after. Both sides ship on one responsive component set, and the brand they sit inside is mine too: the 23-page Shortlet Lagos brand guideline is readable in full on the brand page.</p></div></section><section class=\"case-section\"><h2>What I\u2019d test next</h2><div><p>The question I most want answered is whether people understand what they are buying. A share in a rental property is not an intuitive instrument, and comprehension rather than conversion is the right measure of whether that page works \u2014 a short comprehension test with first-time investors would settle it. I would also check whether guests who arrive to book ever discover the investment side at all, since the two entry points are deliberately separate.</p></div></section><p style=\"margin-top:40px\"><a class=\"button primary\" href=\"https://www.shortlet-lagos.com\" target=\"_blank\" rel=\"noopener\">View shortlet-lagos.com \u2197</a></p></div>"}, {"id": "settle", "content": "<p class=\"drawer-kicker\">Self-initiated \u2014 research in progress</p><h2 id=\"preview-title\">Settle</h2><p class=\"drawer-intro\">The first 30 days in the UK, in the right order: turning a new international student&#x27;s arrival admin into a dependency-aware checklist.</p><dl class=\"drawer-facts\"><div><dt>MY ROLE</dt><dd>Product designer \u2014 research, UX, UI, prototype</dd></div><div><dt>WHEN</dt><dd>4 weeks \u2014 from 12 September 2026</dd></div><div><dt>FOCUS</dt><dd>Service design, task dependency modelling, information architecture</dd></div></dl><img class=\"archive-cover\" src=\"/projects/settle-dependency.jpg\" alt=\"Settle interface overview\" width=\"2560\" height=\"1440\"><div class=\"archive-story\"><section class=\"case-section\"><h2>The short version</h2><div><p>In 2024/25 there were 685,565 international students at UK higher education institutions \u2014 6.1% fewer than the year before, but still the size of a large city arriving every autumn. Almost all of them land with the same cluster of tasks: set up a UKVI eVisa account, enrol, get a proof-of-address letter, open a bank account, register with a GP, apply for a National Insurance number, claim council tax exemption. Universities, UKCISA and GOV.UK all publish accurate lists of these. None of them show which task unlocks which. Settle is my redesign of that first month. I am running it as a real research project rather than a concept piece, and this page is the working record \u2014 published while the research is still open rather than written up afterwards.</p></div></section><section class=\"case-section\"><h2>What I owned</h2><div><p>Everything on this project is mine: framing the problem, designing the study, writing the survey and interview guide, running the competitive review, and the design that follows. I start the MSc at Brighton on 18 September 2026, so the project runs alongside my own first 30 days rather than being written from memory. That is deliberate: I can log my own arrival prospectively, as one data point among several, instead of reconstructing it afterwards and mistaking recall for evidence.</p></div></section><div class=\"metric-row\"><div><strong>7</strong><p>Core tasks in scope for v1</p><small>Project scope</small></div><div><strong>3</strong><p>Falsifiable hypotheses going into research</p><small>Project scope</small></div><div><strong>3</strong><p>Methods \u2014 survey, interviews, competitive review</p><small>Project scope</small></div></div><section class=\"case-section\"><h2>The challenge</h2><div><p>It is not a checklist problem. It is a dependency problem. The clearest case is the proof-of-address loop: a high-street bank asks for proof of a UK address; the usual proof is a university bank letter, which the university will only issue after enrolment and after a term-time address is on record; and some landlords want a UK bank account before they will sign a tenancy. Each counter is individually doing nothing wrong. A student who does not know the order can lose a week moving between the three.</p></div></section><section class=\"case-section\"><h2>The tricky part</h2><div><p>The information is not missing \u2014 it is published, accurate and free. That rules out the obvious product, which would be another list. It also means the design has to earn trust against GOV.UK without impersonating it, and has to be useful to someone whose situation may not match the sequence I experienced. The hard part is establishing whether hidden ordering really is the cause of the pain, or whether the pain sits somewhere else entirely \u2014 appointment availability, language, or simply not knowing who to ask.</p></div></section><section class=\"case-section\"><h2>Research &amp; learning</h2><div><p>Live. Survey open, interviews being recruited from it, competitive review underway. Findings will replace this section as they land.</p><p>Three hypotheses, each written so it can be proved wrong. H1: most students do not know the correct order of tasks on arrival \u2014 falsified if fewer than half score the order as unclear. H2: the bank account is the most painful task, and the cause is proof of address rather than the bank \u2014 tested against the stress ranking and the free-text reasons. H3: students trust peers over official sources, so the product has to read as advice rather than policy \u2014 tested by comparing where information actually comes from against how much it is trusted.</p><p>Whether the dependency map below survives contact with real arrivals. It is modelled from GOV.UK, UKCISA and university guidance rather than from anyone&#x27;s lived sequence, which makes it a hypothesis and not a finding \u2014 halls residents, students with family already in the UK, and anyone arriving mid-year may have a completely different critical path.</p></div></section><section class=\"case-section\"><h2>Design decisions</h2><div><ol><li>Model the tasks as a dependency graph rather than a list \u2014 the unit of design is the edge between two tasks, not the task itself.</li><li>Show the next unlocked step, not everything at once. A blocked step states what unlocks it, so a dead end becomes a direction.</li><li>Attach a &#x27;take with you&#x27; list to every appointment. Nobody should be turned away from a counter for a document nobody told them to bring.</li><li>Explain GP, NI number and council tax once, in plain English, at the point they first appear \u2014 UK-specific vocabulary is a barrier before the admin is.</li><li>Write in the voice of a friend who has done it, with the official source linked underneath: trust without pretending to be GOV.UK.</li></ol></div></section><div class=\"case-gallery\"><figure><img src=\"/projects/settle-dependency.jpg\" alt=\"Dependency map of a new student&#x27;s first 30 days: enrolment and a term-time address unlock the university bank letter, which unlocks the bank account; the eVisa account produces the share code needed for the bank and for the right to work\" loading=\"lazy\" width=\"2560\" height=\"1440\"><figcaption>Dependency map of a new student&#x27;s first 30 days: enrolment and a term-time address unlock the university bank letter, which unlocks the bank account; the eVisa account produces the share code needed for the bank and for the right to work</figcaption></figure></div><section class=\"case-section\"><h2>The evidence</h2><div><p>What exists today is the study design and the problem model: a dependency map, a seven-stage journey map with pain ratings, three falsifiable hypotheses with their measurement criteria, and a scope boundary. No outcomes are claimed because none have been measured yet. This page is deliberately published in that state \u2014 it shows how I work before I have answers, which is the part of the process a finished case study usually hides. It will be updated as findings land.</p></div></section><section class=\"case-section\"><h2>What I\u2019d test next</h2><div><p>The honest risk is that I have modelled this problem from documentation rather than from anyone&#x27;s experience, including my own. A dependency graph drawn from official guidance describes how the system is supposed to work, not how it fails. The study is built to attack that: the hypotheses are written to be falsifiable, the interviews reconstruct each participant&#x27;s actual sequence rather than checking mine, and the survey asks what was hardest before it asks about ordering at all.</p></div></section></div>"}, {"id": "synqit", "content": "<p class=\"drawer-kicker\">Shipped product</p><h2 id=\"preview-title\">Synqit</h2><p class=\"drawer-intro\">Business partnerships that work like friend requests \u2014 sent, reviewed, accepted or declined, with the conversation unlocked only once both sides say yes.</p><dl class=\"drawer-facts\"><div><dt>MY ROLE</dt><dd>Lead product designer, end to end</dd></div><div><dt>WHEN</dt><dd>2026</dd></div><div><dt>FOCUS</dt><dd>Trust-gated matchmaking, partnership requests, controlled access</dd></div></dl><img class=\"archive-cover\" src=\"/projects/synqit-laptop.jpg\" alt=\"Synqit interface overview\" width=\"2000\" height=\"1500\"><div class=\"archive-story\"><section class=\"case-section\"><h2>The short version</h2><div><p>Synqit is a business-driven partnership platform for startups, investment platforms, Web3 projects and crypto companies \u2014 a structured way to find, vet and form strategic partnerships instead of cold-messaging across Twitter, Discord, Telegram and LinkedIn. I led the entire design process across three user roles: businesses and startups looking for partners, investors and project owners looking for opportunities, and the teams and executives who manage the resulting collaborations. The pitch deck the product was raised on is on the brand page.</p></div></section><section class=\"case-section\"><h2>What I owned</h2><div><p>I led the entire design process. I interviewed founders, Web3 teams and investors, built personas for the three roles, defined the partnership request as the core object of the product, and designed the matchmaking, business profile, request-approval and messaging systems around it. I mapped the information architecture, designed the dashboard and mobile-first interface, and ran usability testing with real businesses to refine the trust signals that shipped.</p></div></section><div class=\"metric-row\"><div><strong>3x</strong><p>Improvement in partnership discovery and onboarding</p><small>Reported impact \u00b7 Against the previous scattered, manual process of finding partners across Twitter, Discord, Telegram and LinkedIn</small></div><div><strong>3</strong><p>Role groups in one product \u2014 businesses, investors, project teams</p><small>Project scope</small></div><div><strong>Gated</strong><p>Messaging unlocks only once a partnership request is accepted</p><small>Project scope</small></div></div><section class=\"case-section\"><h2>The challenge</h2><div><p>Startups, Web3 projects and investment platforms struggle to find and connect with the right partners for three reasons that compound each other: there is no basis for trust in a partnership with an unknown company, communication is scattered across multiple channels, and negotiations drag because nothing is structured. Existing networking products treat a connection as a one-sided act \u2014 anyone can message anyone \u2014 which is precisely why they fill with noise and why credible teams stop answering. The product had to give businesses control over who they partner with, make credibility visible before a request is accepted, and move the conversation somewhere structured once it is.</p></div></section><section class=\"case-section\"><h2>The tricky part</h2><div><p>The hard part was deciding what a partnership is, mechanically, before anything could be designed. A follow is too weak \u2014 it commits nobody. An open inbox is too weak in the other direction \u2014 it makes the credible party do the filtering. The model that held was the friend request: a partnership is proposed, the other side reviews the proposer&#x27;s profile and history, and only an acceptance unlocks messaging. That one decision shaped the whole architecture, and it came with a cost: it adds a step and a wait to every connection, in a space where founders are used to firing off a DM. The tension was to keep that deliberate friction \u2014 because it is the product&#x27;s entire answer to the trust problem \u2014 while making everything around it fast. The three roles pulled against each other too: a startup wants to be found, an investor wants to filter, and an executive wants to see the state of every partnership at once, and they all share one dashboard.</p></div></section><section class=\"case-section\"><h2>Research &amp; learning</h2><div><p>Primary research \u2014 interviews, personas and usability testing</p><p>Why business networking fails in this space: no basis for trust, communication scattered across channels, and negotiations that drag because nothing is structured.</p><p>An open inbox makes the credible party do the filtering, which is why credible teams stop answering. Control over who you partner with is the product.</p><p>The partnership request became the core object \u2014 reviewed against a real profile \u2014 and chat was made a consequence of acceptance rather than a starting point.</p><p>How the accept rate moves as profiles get richer, which is the real test of whether visible credibility works.</p></div></section><section class=\"case-section\"><h2>Design decisions</h2><div><ol><li>Interviewed startup founders, Web3 teams and investors to understand where business networking actually breaks, then built personas for the three roles the product had to serve \u2014 businesses seeking partners, investors scouting startups, and teams managing partnerships.</li><li>Defined the partner request as the core object. Users send, review, accept or reject partnership requests, and the dashboard is organised around that state \u2014 pending, accepted and declined \u2014 so the status of every relationship is legible at a glance.</li><li>Made messaging a consequence of acceptance rather than a starting point. The built-in chat activates only once a partnership request is approved, which keeps inboxes free of cold outreach and makes every conversation one both sides chose.</li><li>Designed the business profile as the thing a request is judged against: industry, expertise, past collaborations and key details, visible before anyone sends or accepts \u2014 so the review step has something real to review.</li><li>Designed the matchmaking layer to suggest partners on industry, interests and investment focus, so discovery is a recommendation rather than a search box, and the platform does the first pass of relevance.</li><li>Mapped the full user journey and information architecture \u2014 homepage into sign-up or login, then dashboard, profile setup, account functionality and partnership search \u2014 so every role lands somewhere useful on first login rather than in an empty state.</li><li>Built the interface mobile-first, because the people managing these deals are rarely at a desk when a request arrives.</li><li>Tested the request and messaging features with real businesses and iterated on what they needed to trust it \u2014 verified business profiles, transparent partnership histories, and notifications that keep both sides informed on requests, messages and milestones.</li></ol></div></section><div class=\"case-gallery\"><figure><img src=\"/projects/synqit-user-journey.jpg\" alt=\"The user journey and information architecture: from homepage into sign-up or login, then four destinations \u2014 the dashboard as the main hub with recent partnerships, explore search, match-make and send requests, approve requests and messages; first-time profile setup; account functionality; and partnership search for matchmaking\" loading=\"lazy\" width=\"1600\" height=\"813\"><figcaption>The user journey and information architecture: from homepage into sign-up or login, then four destinations \u2014 the dashboard as the main hub with recent partnerships, explore search, match-make and send requests, approve requests and messages; first-time profile setup; account functionality; and partnership search for matchmaking</figcaption></figure><figure><img src=\"/projects/synqit-deck-problem.jpg\" alt=\"The problem and the solution side by side, as the company framed them: scattered outreach across Twitter, Discord, Telegram and LinkedIn, no verification, high entry barriers and missed partnerships \u2014 answered by smart matchmaking, verified requests, open ecosystem access, AI-powered discovery and one-click outreach\" loading=\"lazy\" width=\"1400\" height=\"788\"><figcaption>The problem and the solution side by side, as the company framed them: scattered outreach across Twitter, Discord, Telegram and LinkedIn, no verification, high entry barriers and missed partnerships \u2014 answered by smart matchmaking, verified requests, open ecosystem access, AI-powered discovery and one-click outreach</figcaption></figure><figure><img src=\"/projects/synqit-deck-mvp.jpg\" alt=\"The MVP release \u2014 AI-powered matching, verified requests, premium visibility and direct messaging \u2014 with the dashboard as shipped\" loading=\"lazy\" width=\"1400\" height=\"788\"><figcaption>The MVP release \u2014 AI-powered matching, verified requests, premium visibility and direct messaging \u2014 with the dashboard as shipped</figcaption></figure><figure><img src=\"/projects/synqit-desk.jpg\" alt=\"Synqit&#x27;s mobile experience shown on a phone alongside a laptop on a desk\" loading=\"lazy\" width=\"2000\" height=\"1333\"><figcaption>Synqit&#x27;s mobile experience shown on a phone alongside a laptop on a desk</figcaption></figure></div><section class=\"case-section\"><h2>What changed</h2><div><p>A partnership-driven platform rather than another networking feed: requests are reviewed against a real profile before anything is accepted, chat exists only between partners who both said yes, matchmaking does the first pass of relevance, and a structured dashboard keeps every active partnership visible. Trust signals \u2014 verified profiles and transparent partnership histories \u2014 became part of the product rather than something users had to establish for themselves on other channels.</p></div></section><section class=\"case-section\"><h2>The evidence</h2><div><p>Testing the request and messaging flows with real businesses shaped the trust signals that shipped. Partnership discovery and onboarding improved threefold against the scattered, manual process the platform replaced. The MVP shipped with AI-powered matching, verified requests, premium visibility and direct messaging, and the full presentation is on Behance; the pitch deck it was raised on is readable on the brand page.</p></div></section><section class=\"case-section\"><h2>What I\u2019d test next</h2><div><p>The request-approval model is the product&#x27;s bet, so the number I would watch is the accept rate on requests and how it moves as profiles get richer \u2014 if credibility is visible, acceptance should rise. I would also test whether the three roles actually want one dashboard or three, since the shared layout was a decision made for coherence and it deserves to be checked against how an investor and a founder really use it.</p></div></section><p style=\"margin-top:40px\"><a class=\"button primary\" href=\"https://www.behance.net/gallery/235692945/Web3-Platform\" target=\"_blank\" rel=\"noopener\">View project presentation \u2197</a></p></div>"}, {"id": "archi-tek", "content": "<p class=\"drawer-kicker\">Concept exploration</p><h2 id=\"preview-title\">Archi-Tek</h2><p class=\"drawer-intro\">Turning a sentence into an editable architectural model \u2014 not just a picture of a building.</p><dl class=\"drawer-facts\"><div><dt>MY ROLE</dt><dd>Product designer</dd></div><div><dt>WHEN</dt><dd>2025</dd></div><div><dt>FOCUS</dt><dd>Conversational AI for professional output, fidelity as a user decision</dd></div></dl><img class=\"archive-cover\" src=\"/projects/architek-prompt.jpg\" alt=\"Archi-Tek interface overview\" width=\"1000\" height=\"632\"><div class=\"archive-story\"><section class=\"case-section\"><h2>The short version</h2><div><p>Archi-Tek is a text-to-design tool for architecture. Describe a building in plain language and it generates concept sketches, schematic plans or detailed models \u2014 then hands you the result as a real CAD file you can keep working in. I designed the end-to-end product: the prompt experience, the design-type system, the preview and export flow, and the 3D editor.</p></div></section><section class=\"case-section\"><h2>What I owned</h2><div><p>I designed the end-to-end product: the prompt experience and its starting points, the design-type system that makes fidelity an explicit choice, the results gallery, the preview and export flow, and the 3D editor interface. I set the principle the product rests on \u2014 that the output has to leave as a working CAD file rather than an image.</p></div></section><div class=\"metric-row\"><div><strong>3</strong><p>Fidelity modes \u2014 Concept Sketch, Schematic Plan, Detailed Model</p><small>Project scope</small></div><div><strong>4</strong><p>Export formats designed \u2014 DWG, OBJ, SKP, PDF</p><small>Project scope</small></div><div><strong>Coming soon</strong><p>The in-product 3D editor, staged honestly rather than implied</p><small>Project scope</small></div></div><section class=\"case-section\"><h2>The challenge</h2><div><p>Generative AI is good at producing a convincing picture of a building. That is precisely what an architect cannot use. A render is a dead end: it cannot be dimensioned, measured, revised or handed to an engineer. Meanwhile the tools that do produce workable geometry \u2014 CAD and 3D modelling suites \u2014 carry a learning curve measured in months, which puts early-stage massing and client-facing concepts out of reach for the people who most need them quickly. The design problem was to sit a conversational interface on top of real architectural output, without either half undermining the other: the chat could not feel like a toy, and the output could not be a JPEG.</p></div></section><section class=\"case-section\"><h2>The tricky part</h2><div><p>Generative models are good at producing a convincing picture of a building, which is the one thing an architect cannot use \u2014 a render cannot be dimensioned, revised or handed to an engineer. Putting a conversational front end onto real geometry meant neither half could undermine the other: the chat could not feel like a toy, and the output could not be a JPEG. The sharper constraint was capability. The in-product 3D editor did not exist yet, so the interface had to communicate the workflow it belongs to without implying it was available \u2014 which is why it is staged in the UI as coming soon rather than presented as working. Overstating it would have been the easier design and the wrong one.</p></div></section><section class=\"case-section\"><h2>Research &amp; learning</h2><div><p>Exploratory, product-design-led</p><p>What makes generative output unusable in architecture \u2014 the finding was that a render cannot be dimensioned, revised or handed to an engineer.</p><p>Fidelity is a decision the user should make, not one the model should guess: a quick massing study and a dimensioned model have different tolerances for error.</p><p>The interface asks for design type up front in plain language, and export formats sit beside the generated design so the nature of the output is unambiguous.</p><p>Whether an exported DWG is genuinely workable \u2014 the claim the whole product rests on, and untested.</p></div></section><section class=\"case-section\"><h2>Design decisions</h2><div><ol><li>Framed the core insight that fidelity is a decision the user makes, not one the model should guess. A quick massing study and a dimensioned model are different jobs with different tolerances for error, so the interface asks up front \u2014 Concept Sketch, Schematic Plan or Detailed Model \u2014 and describes each in plain language rather than jargon.</li><li>Designed the prompt screen around the blank-page problem. A bare text field asks the user to already know what to say, so the entry point pairs a single open field with typed starting points \u2014 3-Bedroom Bungalow, Duplex Sample, 3-Story Building, Filling Station \u2014 and a wall of generated samples underneath, so the first move is recognition rather than recall.</li><li>Structured the results as a browsable gallery of named, comparable options (Modern Villa, Neo-Classical Duplex, Urban Courtyard Duplex) rather than a single answer. Architectural ideation is comparative; showing one output invites acceptance instead of judgement.</li><li>Made export the moment of trust. The preview modal puts format selection \u2014 DWG, OBJ, SKP, PDF \u2014 directly beside the generated design, so it is unambiguous from first use that the output is a working file destined for AutoCAD, Blender or SketchUp, not an image to screenshot.</li><li>Designed the in-product 3D editor as the continuation of that promise: a familiar viewport with orientation gizmo, object-mode toolbar and its own Export Design action, so refinement does not require leaving the tool \u2014 and staged it honestly in the UI as coming soon rather than implying capability that is not there yet.</li><li>Kept the chat conversational and the workspace professional, using a restrained neutral interface so the generated architecture is the only thing on screen carrying colour and detail.</li></ol></div></section><div class=\"case-gallery\"><figure><img src=\"/projects/architek-design-type.jpg\" alt=\"Design type modal offering Concept Sketch, Schematic Plan and Detailed Model, each with a plain-language description of what it is for\" loading=\"lazy\" width=\"1000\" height=\"632\"><figcaption>Design type modal offering Concept Sketch, Schematic Plan and Detailed Model, each with a plain-language description of what it is for</figcaption></figure><figure><img src=\"/projects/architek-preview.jpg\" alt=\"Preview modal showing a generated design with download format options \u2014 DWG, OBJ, SKP and PDF \u2014 and an entry point into the Archi-Tek editor\" loading=\"lazy\" width=\"1000\" height=\"632\"><figcaption>Preview modal showing a generated design with download format options \u2014 DWG, OBJ, SKP and PDF \u2014 and an entry point into the Archi-Tek editor</figcaption></figure><figure><img src=\"/projects/architek-editor.jpg\" alt=\"The Archi-Tek 3D editor: a viewport with orientation gizmo, object-mode toolbar and an Export Design action\" loading=\"lazy\" width=\"1005\" height=\"632\"><figcaption>The Archi-Tek 3D editor: a viewport with orientation gizmo, object-mode toolbar and an Export Design action</figcaption></figure></div><section class=\"case-section\"><h2>What changed</h2><div><p>An AI design assistant that behaves like a drafting collaborator rather than an image generator: fidelity chosen deliberately, options compared side by side, and every result leaving the product as an editable CAD file. The flow moves from a sentence, through a design-type decision and a compared set of options, to a downloadable model \u2014 with an editor waiting for the work that follows.</p></div></section><section class=\"case-section\"><h2>The evidence</h2><div><p>Fidelity is a decision the user makes rather than one the model guesses. Results are presented as comparable named options instead of a single answer, and the export formats \u2014 DWG, OBJ, SKP and PDF \u2014 sit beside the generated design, so the nature of the output is unambiguous before anyone invests time in it. The full presentation is published on Behance.</p></div></section><section class=\"case-section\"><h2>What I\u2019d test next</h2><div><p>This needs practising architects and a real file. The test that matters is whether an exported DWG opens in AutoCAD and survives being edited \u2014 if the geometry is not workable, the clarity of the interface counts for nothing. I would also check whether the three fidelity levels match how architects actually think about early-stage work, or whether they are a designer&#x27;s categories rather than a practitioner&#x27;s.</p></div></section><p style=\"margin-top:40px\"><a class=\"button primary\" href=\"https://www.behance.net/gallery/235692645/Chat-Gpt-like-Product-design-for-Architectural-design\" target=\"_blank\" rel=\"noopener\">View project presentation \u2197</a></p></div>"}, {"id": "loan-investment-app", "content": "<p class=\"drawer-kicker\">Prototype</p><h2 id=\"preview-title\">Loan &amp; Investment App</h2><p class=\"drawer-intro\">Borrowing, investing, banking, insurance and bills in one app \u2014 without any of them losing their meaning.</p><dl class=\"drawer-facts\"><div><dt>MY ROLE</dt><dd>Product designer</dd></div><div><dt>WHEN</dt><dd>2025</dd></div><div><dt>FOCUS</dt><dd>Responsible simplification \u2014 clarity without hiding risk</dd></div></dl><img class=\"archive-cover\" src=\"/projects/loan-home.jpg\" alt=\"Loan &amp; Investment App interface overview\" width=\"948\" height=\"632\"><div class=\"archive-story\"><section class=\"case-section\"><h2>The short version</h2><div><p>A Nigerian fintech super-app that combines lending, investing, everyday banking, property insurance and bill payments in a single product. I designed the mobile experience across those journeys \u2014 the home dashboard, the loan flow, and the investment and transaction surfaces \u2014 with an emphasis on stating plainly what money is doing at every step.</p></div></section><section class=\"case-section\"><h2>What I owned</h2><div><p>I designed the mobile experience across five financial products \u2014 the home dashboard and single balance, the loan request flow and its empty states, the investment and equity purchase journey, transaction and payment design, and the mobile design system that holds them together as one institution rather than four bolted-together apps.</p></div></section><div class=\"metric-row\"><div><strong>5</strong><p>Financial products in one app</p><small>Project scope \u00b7 Lending, investing, banking, insurance and bill payments</small></div><div><strong>\u20a6100,000</strong><p>Minimum investment, surfaced before commitment rather than after</p><small>Project scope</small></div><div><strong>1</strong><p>Balance anchoring the home screen, not five</p><small>Project scope</small></div></div><section class=\"case-section\"><h2>The challenge</h2><div><p>Most people end up running their financial life across four or five apps: one to borrow, one to save, one to invest, another for bills and insurance. Consolidating them is easy to propose and difficult to design well. Each product carries its own risk profile, its own regulatory language and its own vocabulary, and stacking them tends to produce one of two failures \u2014 a dashboard so dense that nothing is findable, or an interface so friendly that it quietly obscures what a decision actually costs. Investing raises the stakes further: a product that makes buying equities feel as frictionless as ordering food has not removed complexity, it has hidden risk. The problem was to hold five financial products in one app while keeping each one legible enough to be trusted with real money.</p></div></section><section class=\"case-section\"><h2>The tricky part</h2><div><p>Making investing feel as easy as ordering food is the obvious way to grow the product and the fastest way to do harm \u2014 friction removed from a risk decision does not remove the risk, it hides it. Every simplification had to be checked against whether it made the money clearer or merely made the screen calmer. That is why a projected return is labelled indicative value at maturity and stated gross of withholding tax at the moment of commitment rather than in a footnote, and why the minimum investment and the wallet balance appear before the button instead of arriving as an error after it. The competing pull was consolidation itself: five products in one app tends to produce either a dashboard too dense to navigate or a friendliness that flattens the difference between borrowing and investing, which are not the same kind of decision at all.</p></div></section><section class=\"case-section\"><h2>Research &amp; learning</h2><div><p>Exploratory, product-design-led</p><p>Where consolidation helps and where it harms \u2014 specifically whether simplifying an investment decision makes it clearer or merely calmer.</p><p>Friction removed from a risk decision does not remove the risk, it hides it. Borrowing and investing are not the same kind of decision and should not feel identical.</p><p>Projections are labelled indicative value at maturity and stated gross of withholding tax at the point of commitment, and constraints like the \u20a6100,000 minimum appear before the button rather than as an error after it.</p><p>Whether people read those labels as estimates rather than promises.</p></div></section><section class=\"case-section\"><h2>Design decisions</h2><div><ol><li>Anchored the home screen on one balance rather than five. Everything else \u2014 quick actions, savings prompts, pending tasks \u2014 arranges itself around that single number, so the first question the app answers is always the one people actually open it to ask.</li><li>Designed for use in public. The balance masks by default behind a reveal control, because the realistic context for this app is a phone held on a street or in a queue, not a desk.</li><li>Turned empty states into the teaching moment. With no active loan, the screen does not simply report \u20a60.00 \u2014 it explains what borrowing here is for (daily expenses, personal goals, business growth) before offering a single Request Loan action, so a first-time user learns the product at the point they are considering it.</li><li>Surfaced every constraint before commitment, not after it. The \u20a6100,000 minimum sits under the amount field as you type, and the wallet balance appears beside the payment method, so the two most common causes of a failed transaction are visible before the button is pressed rather than reported as an error afterwards.</li><li>Wrote the investment language to be honest rather than flattering. A projected return is labelled indicative value at maturity and stated gross of withholding tax \u2014 the interface tells you the number is an estimate and that tax has not yet been taken out, at the exact moment you are deciding how much to commit.</li><li>Kept transactions in context using bottom sheets over the instrument&#x27;s own price chart, so committing money never fully hides the performance data the decision rests on.</li><li>Unified five products under one restrained visual system \u2014 a warm gold accent on near-black and white \u2014 so moving from a loan to an equity purchase to a bill payment feels like one institution rather than four bolted-together apps.</li></ol></div></section><div class=\"case-gallery\"><figure><img src=\"/projects/loan-myloan.jpg\" alt=\"The loan screen with no active loan: rather than an empty balance, it explains what a loan can be used for \u2014 daily expenses, personal goals, business growth \u2014 above a single Request Loan action\" loading=\"lazy\" width=\"843\" height=\"632\"><figcaption>The loan screen with no active loan: rather than an empty balance, it explains what a loan can be used for \u2014 daily expenses, personal goals, business growth \u2014 above a single Request Loan action</figcaption></figure><figure><img src=\"/projects/loan-equities.jpg\" alt=\"Buying equities: indicative value at maturity stated gross of withholding tax, the minimum investment shown beneath the amount field, and wallet balance surfaced beside the payment method before Buy Now\" loading=\"lazy\" width=\"1800\" height=\"1041\"><figcaption>Buying equities: indicative value at maturity stated gross of withholding tax, the minimum investment shown beneath the amount field, and wallet balance surfaced beside the payment method before Buy Now</figcaption></figure></div><section class=\"case-section\"><h2>What changed</h2><div><p>A super-app that earns the breadth it claims: five financial products sharing one balance, one visual language and one standard of disclosure. Constraints appear before commitment, projections are labelled as projections, and empty states teach rather than stall \u2014 so consolidation makes the user&#x27;s financial picture clearer instead of merely shorter.</p></div></section><section class=\"case-section\"><h2>The evidence</h2><div><p>One balance anchors the home screen rather than five. Constraints are surfaced before commitment rather than reported as failures afterwards, projections are labelled as estimates with tax status stated at the point of decision, and empty states explain the product rather than reporting zero. The full presentation is published on Behance.</p></div></section><section class=\"case-section\"><h2>What I\u2019d test next</h2><div><p>I would test whether people actually read indicative value at maturity as an estimate rather than a promise \u2014 that phrase is carrying a lot of weight, and its comprehension is testable in minutes. I would also check whether masking the balance by default helps or irritates in daily use, since it trades a small constant cost against a privacy benefit that only matters occasionally.</p></div></section><p style=\"margin-top:40px\"><a class=\"button primary\" href=\"https://www.behance.net/gallery/235692477/Loan-Investment-Mobile-App\" target=\"_blank\" rel=\"noopener\">View project presentation \u2197</a></p></div>"}, {"id": "project-management-dashboard", "content": "<p class=\"drawer-kicker\">Shipped product</p><h2 id=\"preview-title\">Reporting Portal</h2><p class=\"drawer-intro\">A KPI-first reporting dashboard where the numbers that imply an action come before the ones that merely reassure.</p><dl class=\"drawer-facts\"><div><dt>MY ROLE</dt><dd>Product designer</dd></div><div><dt>WHEN</dt><dd>2025</dd></div><div><dt>FOCUS</dt><dd>KPI-first reporting, risk visibility, light and dark themes</dd></div></dl><img class=\"archive-cover\" src=\"/projects/pm-dashboard-laptop.jpg\" alt=\"Reporting Portal interface overview\" width=\"2000\" height=\"1500\"><div class=\"archive-story\"><section class=\"case-section\"><h2>The short version</h2><div><p>Reporting Portal is a project management dashboard built around a KPI-first overview: a key-metrics row for total projects, tasks due, at-risk and critical items; a filter bar across project, team, date range and status; and a task board moving work through To Do, In Progress, Review and Done alongside upcoming milestones. It ships in light and dark themes and adapts down to mobile. This is a selected project rather than a full case study \u2014 the complete presentation is published on Behance.</p></div></section><section class=\"case-section\"><h2>What I owned</h2><div><p>I designed the reporting portal&#x27;s dashboard and information architecture: the key-metrics row, the filter model, the four-state task board, the milestone view and the responsive layout, in both light and dark themes.</p></div></section><div class=\"metric-row\"><div><strong>4</strong><p>Task states \u2014 To Do, In Progress, Review, Done</p><small>Project scope</small></div><div><strong>4</strong><p>Filter dimensions \u2014 project, team, date range, status</p><small>Project scope</small></div><div><strong>2</strong><p>Themes \u2014 light and dark, designed as equals</p><small>Project scope</small></div></div><section class=\"case-section\"><h2>The challenge</h2><div><p>A reporting dashboard is opened to answer one question \u2014 what needs attention today \u2014 but it is usually built to answer a different one: how much work exists. Totals are easy to produce and reassuring to look at, and they tell a manager nothing they can act on. The design problem was to decide what earns the top of the screen when the person reading it is scanning, not studying, and often doing it on a phone between meetings.</p></div></section><section class=\"case-section\"><h2>The tricky part</h2><div><p>Prioritising risk means accepting an uncomfortable default: the dashboard opens by showing what is going wrong. That is the honest view and it is not the one a stakeholder demoing the tool tends to want, so the metrics row had to earn its order \u2014 total projects stays, because context matters, but tasks due, at-risk and critical sit alongside it rather than beneath it. The second constraint was breadth: four filter dimensions, four task states, milestones and two themes all had to survive being compressed onto a phone without becoming a stack of disconnected cards.</p></div></section><section class=\"case-section\"><h2>Research &amp; learning</h2><div><p>Exploratory, product-design-led</p><p>What belongs above the fold on a dashboard whose users are scanning rather than reading.</p><p>Totals are reassuring and useless; the useful figures are the ones that imply an action \u2014 what is due, what is at risk, what is critical.</p><p>The key-metrics row leads with tasks due, at-risk and critical items rather than a project count, and milestones sit beside the board rather than in a separate view.</p><p>Whether the four task states match how teams really move work, or whether they need a blocked state.</p></div></section><section class=\"case-section\"><h2>Design decisions</h2><div><ol><li>Led the metrics row with figures that imply an action \u2014 tasks due, at-risk and critical items \u2014 rather than with a project count, so the first thing read is the first thing to do.</li><li>Put the task board and upcoming milestones on the same screen, because the question &#x27;is this on track&#x27; is answered by the two of them together and not by either alone.</li><li>Designed four task states \u2014 To Do, In Progress, Review and Done \u2014 with Review as its own column rather than a flag, so work waiting on someone is visible rather than buried inside In Progress.</li><li>Built filtering across the four dimensions a manager actually slices by \u2014 project, team, date range and status \u2014 and kept the filter bar in view, so refining never means losing the results.</li><li>Designed light and dark themes as equals rather than treating dark as an afterthought, with status colour tested for legibility in both.</li><li>Reduced the layout for mobile around the metrics row and a single board column, so the at-a-glance answer survives the smallest screen the tool is opened on.</li></ol></div></section><div class=\"case-gallery\"><figure><img src=\"/projects/pm-dashboard-light.jpg\" alt=\"Reporting Portal in light mode: key metrics row, filter bar, and a four-column task board beside upcoming milestones\" loading=\"lazy\" width=\"996\" height=\"632\"><figcaption>Reporting Portal in light mode: key metrics row, filter bar, and a four-column task board beside upcoming milestones</figcaption></figure><figure><img src=\"/projects/pm-dashboard-dark.jpg\" alt=\"The same dashboard in dark mode, with the metric cards and task board colour-coded by status\" loading=\"lazy\" width=\"996\" height=\"632\"><figcaption>The same dashboard in dark mode, with the metric cards and task board colour-coded by status</figcaption></figure><figure><img src=\"/projects/pm-dashboard-phone.jpg\" alt=\"Reporting Portal&#x27;s mobile layout shown on a phone\" loading=\"lazy\" width=\"843\" height=\"632\"><figcaption>Reporting Portal&#x27;s mobile layout shown on a phone</figcaption></figure></div><section class=\"case-section\"><h2>What changed</h2><div><p>A dashboard that opens on the work needing attention rather than on a summary of everything: risk and due-date pressure at the top, a four-state board that surfaces work waiting on a person, milestones in the same view, and a filter model that answers a manager&#x27;s real questions. It holds up in light and dark and down to a phone.</p></div></section><section class=\"case-section\"><h2>The evidence</h2><div><p>The metrics row leads with tasks due, at-risk and critical items rather than totals; Review exists as its own column so blocked work is visible; and the layout survives both themes and a mobile breakpoint. The full presentation is published on Behance.</p></div></section><section class=\"case-section\"><h2>What I\u2019d test next</h2><div><p>Test whether managers can identify the day&#x27;s at-risk items within a few seconds of opening the dashboard, and whether four task states are sufficient in practice or whether teams need a blocked state distinct from Review.</p></div></section><p style=\"margin-top:40px\"><a class=\"button primary\" href=\"https://www.behance.net/gallery/235694983/Project-Management-Dashboard\" target=\"_blank\" rel=\"noopener\">View project presentation \u2197</a></p></div>"}]);const featuredDetails={"bizinc": "<p class=\"drawer-kicker\">Live product</p><h2 id=\"preview-title\">Bizinc</h2><p class=\"drawer-intro\">One platform where a business is found, booked and run \u2014 discovery on one side, operations on the other.</p><dl class=\"drawer-facts\"><div><dt>MY ROLE</dt><dd>UI/UX Intern \u2192 Product Designer \u2192 UI/UX Manager, BIZINC</dd></div><div><dt>WHEN</dt><dd>April 2024 \u2013 May 2026</dd></div><div><dt>FOCUS</dt><dd>Two-sided marketplace UX, booking flows, operator dashboards, design system</dd></div></dl><img class=\"archive-cover\" src=\"/projects/bizinc-home.jpg\" alt=\"Bizinc interface overview\" width=\"2000\" height=\"1121\"><div class=\"archive-story\"><section class=\"case-section\"><h2>The short version</h2><div><p>Bizinc is an all-in-one marketplace platform: customers discover local businesses and book services, and those businesses manage their operations and grow their brand from the same account. Two products, two audiences and one account between them. I joined remotely in April 2024, two years before the engagement ended, and moved from intern to designer to UI/UX Manager over that time.</p></div></section><section class=\"case-section\"><h2>What I owned</h2><div><p>I designed Bizinc from scratch. I framed the problem with the founding team, mapped the sign-up, business-owner and client journeys, reconciled them into one site map, wrote the Business Profile 2.0 requirements, wireframed at desktop scale, and designed the marketplace, booking, deals, services, products and dashboard surfaces in high fidelity. I built the component library the rest of the team designed against \u2014 Auto Layout, variants and design tokens \u2014 and versioned the file from v1.2 to v2.0 to a development-ready page.</p></div></section><div class=\"metric-row\"><div><strong>+45%</strong><p>User activation on the dashboard</p><small>Reported impact</small></div><div><strong>+23%</strong><p>Customer growth across the redesign period</p><small>Company traction \u00b7 Bizinc&#x27;s own figure, measured over the redesign period</small></div><div><strong>+12%</strong><p>Customer-to-customer service activity</p><small>Reported impact</small></div></div><p class=\"metric-note\">Reported figures from the existing project record across the redesign period; individual design changes were not separately attributed.</p><section class=\"case-section\"><h2>The challenge</h2><div><p>A marketplace has to satisfy two people whose interests only partly overlap. Someone looking for a service wants to find a business, judge whether to trust it and book it in a few minutes, on a phone, without learning a system first. The business on the other side needs the opposite kind of product \u2014 somewhere to run those bookings, manage its listing and see whether any of it is actually bringing customers in. Building both into one platform, across service categories that book quite differently, risks two failures: a customer experience buried under operator tooling, or an operator experience reduced to a profile page no business would actually run on. The problem was to make one platform legible from both directions without maintaining two disconnected products.</p></div></section><section class=\"case-section\"><h2>The tricky part</h2><div><p>The hardest part was Business Profile 2.0 \u2014 one profile serving an owner who edits it and a visitor who judges it. Deciding field by field what an owner controls, what a visitor sees instead, and what belongs to neither is the kind of thing that quietly becomes two disconnected products if it is never settled explicitly. Working it out as a written requirements list, business view beside client view, was slower than designing screens directly and it was the only way to make each difference deliberate rather than accidental. Redesigning in place added a second constraint: the platform was already live with businesses on it, so v2.0 had to be a version people could be moved to, not a fresh start.</p></div></section><section class=\"case-section\"><h2>Research &amp; learning</h2><div><p>Product-design-led, with stakeholder discovery</p><p>Where one profile has to serve an owner who edits it and a visitor who judges it, and which signals actually decide an enquiry.</p><p>The two views diverge field by field, and leaving that implicit was quietly producing two disconnected products.</p><p>Business Profile 2.0 was specified as a written requirements list, business view beside client view, before any screen was drawn.</p><p>Which parts of the redesign drove the activation and growth figures \u2014 the numbers are aggregate, not attributed.</p></div></section><section class=\"case-section\"><h2>Design decisions</h2><div><ol><li>Mapped the two audiences as separate flows before drawing a single screen \u2014 sign-up, business-owner and client journeys side by side \u2014 then reconciled them into one site map, so where the paths diverge and where they share a screen was a decision rather than an accident.</li><li>Specified Business Profile 2.0 as requirements in top-down order, business view beside client view. Laying the two lists against each other made every difference deliberate: what an owner can edit, what a visitor sees instead, and which fields belong to neither.</li><li>Wireframed at desktop scale before any visual design \u2014 profile, search, dashboard, marketing tools, listings and the community forum \u2014 so layout and hierarchy were settled while they were still cheap to change.</li><li>Designed discovery for people who are comparing, not browsing. Business cards lead with the signals that decide an enquiry \u2014 what the business does, where it is, how far away, whether it is open right now \u2014 so a shortlist forms without opening five tabs.</li><li>Treated the business dashboard as the product operators run on, not a settings screen: listing management, deals, services and products, and performance sit together, so being discoverable and being operational are not two separate tools.</li><li>Kept the marketing and lead-generation surfaces inside that dashboard rather than bolting them on, so the line from a listing to the enquiries it produces to what the owner does next stays visible in one place.</li><li>Designed the AI assistant as a way into the marketplace rather than a support widget, and tied it to the map: it asks what you need, reads where you are, and returns real businesses nearby with availability you can act on \u2014 so the conversation ends in a booking instead of a link, and a small local business becomes findable to someone who did not know its name.</li><li>Built the interface as reusable components with Auto Layout, variants and design tokens, and versioned the file from v1.2 through v2.0 to a development-ready page \u2014 so consistency survived the redesign and engineering had one place to build from.</li><li>Worked directly with stakeholders to turn business requirements into interface decisions, and kept every journey responsive from the first wireframe, since the customer side is used mostly on a phone and the operator side mostly at a desk.</li></ol></div></section><div class=\"case-gallery\"><figure><img src=\"/projects/bizinc-flows.jpg\" alt=\"The structural work behind the product: sign-up, business-owner and client user flows mapped side by side, the MVP 2.0 support notes, the full site map, and the mobile screens grouped by journey \u2014 account creation, business and client profiles, lists and deals, services and products\" loading=\"lazy\" width=\"2284\" height=\"1148\"><figcaption>The structural work behind the product: sign-up, business-owner and client user flows mapped side by side, the MVP 2.0 support notes, the full site map, and the mobile screens grouped by journey \u2014 account creation, business and client profiles, lists and deals, services and products</figcaption></figure><figure><img src=\"/projects/bizinc-wireframes.jpg\" alt=\"Seven desktop wireframes resolving layout before visual design \u2014 profile, search results, performance dashboard, business profile, marketing tools with spotlight recommendations and promotion opportunities, listings, and the community forum\" loading=\"lazy\" width=\"2222\" height=\"1028\"><figcaption>Seven desktop wireframes resolving layout before visual design \u2014 profile, search results, performance dashboard, business profile, marketing tools with spotlight recommendations and promotion opportunities, listings, and the community forum</figcaption></figure><figure><img src=\"/projects/bizinc-requirements.jpg\" alt=\"Business Profile 2.0 specified as requirements in top-down order, business view beside client view \u2014 so the two audiences could be compared field by field and the difference between them decided deliberately rather than by omission\" loading=\"lazy\" width=\"2000\" height=\"1517\"><figcaption>Business Profile 2.0 specified as requirements in top-down order, business view beside client view \u2014 so the two audiences could be compared field by field and the difference between them decided deliberately rather than by omission</figcaption></figure><figure><img src=\"/projects/bizinc-figma.jpg\" alt=\"The working Figma file: v1.2 and v2.0 desktop and mobile pages, a components page and a development-ready page, with the AI integration revamp and the Bizzy assistant conversation open on the canvas\" loading=\"lazy\" width=\"2000\" height=\"1269\"><figcaption>The working Figma file: v1.2 and v2.0 desktop and mobile pages, a components page and a development-ready page, with the AI integration revamp and the Bizzy assistant conversation open on the canvas</figcaption></figure></div><section class=\"case-section\"><h2>What changed</h2><div><p>A platform that works from both ends \u2014 customers discover and book services, businesses run those bookings and see where their customers came from \u2014 held together by one component library across booking, e-commerce and SaaS surfaces. Onboarding was smoothed so fewer people fall out before they have an account, discovery became proximity-aware rather than a flat directory, and the operator dashboard gave owners a reason to return between bookings. The product is live at bizinc.io.</p></div></section><section class=\"case-section\"><h2>The evidence</h2><div><p>The redesign moved the numbers the business tracks: a 23% increase in customers across the redesign period, a 12%+ increase in customer-to-customer service activity, and a 45% improvement in user activation on the dashboard and lead-generation experiences, alongside growth in profile creation and stronger retention. The product is live at bizinc.io, and Bizinc&#x27;s CEO has written a reference describing the platform rebuild and the progression to UI/UX Manager, published in full on the credentials page.</p></div></section><section class=\"case-section\"><h2>What I\u2019d test next</h2><div><p>The headline numbers tell me the redesign worked; they do not yet tell me which parts did the work. I would instrument the discovery path specifically \u2014 whether the open-now, distance and category signals on a business card actually shorten the route to an enquiry \u2014 and test the AI assistant with people who have never used the platform, since its value depends entirely on a stranger trusting it enough to start the conversation. On the operator side, I would want to know whether owners find the marketing surfaces inside the dashboard or work around them.</p></div></section><p style=\"margin-top:40px\"><a class=\"button primary\" href=\"https://www.bizinc.io\" target=\"_blank\" rel=\"noopener\">View bizinc.io \u2197</a></p></div>", "vista-itss": "<p class=\"drawer-kicker\">Shipped product</p><h2 id=\"preview-title\">Vista Digital Banking</h2><p class=\"drawer-intro\">One banking app for businesses operating across four markets \u2014 entities, currencies and approval mandates included.</p><dl class=\"drawer-facts\"><div><dt>MY ROLE</dt><dd>UI/UX Designer &amp; Front-End Developer, ITSS</dd></div><div><dt>WHEN</dt><dd>May 2022 \u2013 April 2024</dd></div><div><dt>FOCUS</dt><dd>Multi-entity, multi-currency banking; approval workflows; a design system spanning four subsidiaries</dd></div></dl><img class=\"archive-cover\" src=\"/projects/vista-devices.jpg\" alt=\"Vista Digital Banking interface overview\" width=\"1800\" height=\"1350\"><div class=\"archive-story\"><section class=\"case-section\"><h2>The short version</h2><div><p>Vista is a banking group operating across several West African markets. I joined ITSS in May 2022 as an intern on the programme and moved onto staff during it, working on the digital banking product \u2014 corporate and retail \u2014 through to April 2024, covering onboarding and identity verification, account dashboards, transfer and approval journeys. The work was recognised with ITSS&#x27;s Most Outstanding Intern of the Year award for my contribution to Vista. The role spanned UI design, digital and graphic design for campaigns, and front-end work, delivered across four localised market subsidiaries \u2014 Gambia, Guinea, Sierra Leone and Burkina Faso.</p></div></section><section class=\"case-section\"><h2>What I owned</h2><div><p>I designed the digital banking product across corporate and retail journeys \u2014 onboarding and identity verification, account dashboards, transfers, approval mandates, secure messaging and payments \u2014 for four localised market subsidiaries. I built one design system that held across all four while allowing local differences in language, currency and regulatory copy, produced the campaign and graphic design that sat on top of it, and reviewed front-end builds in HTML/CSS to keep implementation faithful to the designs.</p></div></section><div class=\"metric-row\"><div><strong>4</strong><p>West African markets \u2014 Gambia, Sierra Leone, Guinea, Burkina Faso</p><small>Project scope</small></div><div><strong>4</strong><p>Localised subsidiaries on one design system</p><small>Project scope</small></div><div><strong>2</strong><p>Languages \u2014 English and French, selected at sign-in</p><small>Project scope</small></div></div><section class=\"case-section\"><h2>The challenge</h2><div><p>Business banking in a multi-market group breaks the assumption every consumer banking app is built on: that one person means one account in one currency in one country. A Vista customer might be a finance manager holding mandates over several legal entities across Gambia, Guinea, Sierra Leone and Burkina Faso, each with its own currency, its own regulator and its own local rules \u2014 and payments they initiate may need someone else&#x27;s approval before money moves. Designing for that means holding real institutional complexity on a phone screen without either flattening it into something unsafe or exposing all of it at once. The subsidiaries added a second problem on top: four markets \u2014 anglophone and francophone, each with its own currency and regulator \u2014 needed to feel like one bank without ignoring what made each of them local.</p></div></section><section class=\"case-section\"><h2>The tricky part</h2><div><p>Four subsidiaries \u2014 Gambia, Sierra Leone, Guinea and Burkina Faso \u2014 each with its own currency, regulator and language meant every shared screen had to survive four sets of local requirements without fragmenting into four products. Anglophone and francophone markets pushed language selection up into sign-in rather than leaving it in settings: a small decision with a large consequence, because it sits in front of the most sensitive screen in the app. Corporate banking then broke the assumption the retail patterns were built on \u2014 one person, one account, one currency, one country \u2014 so patterns that worked for retail customers had to be rethought rather than reused for a finance manager holding mandates across several legal entities.</p></div></section><section class=\"case-section\"><h2>Research &amp; learning</h2><div><p>Requirements-led discovery with product and engineering teams</p><p>Whether the retail patterns could carry corporate banking, where one person may act for several entities in different currencies and regulators.</p><p>They could not. Corporate banking breaks the one-person-one-account assumption the retail flows were built on, and approvals are other people&#x27;s work waiting on you rather than notifications.</p><p>Entity became top-level context beneath the user&#x27;s name rather than a setting, and pending approvals moved above the fold on the accounts screen with their own counts.</p><p>Post-launch adoption and task-completion behaviour, which I did not have access to.</p></div></section><section class=\"case-section\"><h2>Design decisions</h2><div><ol><li>Made entity the top-level context rather than a setting. The switcher sits directly beneath the user&#x27;s name and last sign-in on the menu screen, so which legal entity and market you are acting in is answered before any transaction begins \u2014 the question that determines what every subsequent number and permission means.</li><li>Designed approvals as a first-class destination, not a notification. Pending requests \u2014 bulk payment, single payment, other \u2014 are surfaced above the fold on the accounts screen with their own counts, because in corporate banking the blocking task is usually someone else&#x27;s payment waiting on you.</li><li>Built filtering for people who hold many accounts. Default and custom views, sorting by name or balance, and account-type selection let a user with dozens of accounts across entities save the shape they actually work in, rather than scrolling a flat list every session.</li><li>Kept balances in local currency and led with available balance rather than ledger balance, since the practical question before a transfer is what can actually be moved today.</li><li>Anchored navigation on the four things corporate users return to \u2014 accounts, transfers, messages and menu \u2014 and kept secure messaging and support inside the app, because for business banking the alternative is a branch visit.</li><li>Treated last sign-in, session state and language selection as trust signals rather than clutter, surfacing them where an account holder checks for anything unexpected.</li><li>Built one design system across the four subsidiaries so shared journeys stayed consistent while local requirements, languages and regulatory copy could vary. With Gambia and Sierra Leone operating in English and Guinea and Burkina Faso in French, language selection had to be a first-class part of the sign-in experience rather than a setting found later.</li><li>Carried the same visual system into campaign and graphic design for the product, and used HTML/CSS to review front-end builds against the designs, keeping interfaces responsive and pixel-accurate through implementation.</li></ol></div></section><div class=\"case-gallery\"><figure><img src=\"/projects/vista-menu.jpg\" alt=\"The menu screen, where the entity switcher sits directly under the user&#x27;s name and last sign-in \u2014 one person moving between the legal entities and countries they hold mandates for, above transfer activities, recipient management and approvals\" loading=\"lazy\" width=\"740\" height=\"1600\"><figcaption>The menu screen, where the entity switcher sits directly under the user&#x27;s name and last sign-in \u2014 one person moving between the legal entities and countries they hold mandates for, above transfer activities, recipient management and approvals</figcaption></figure><figure><img src=\"/projects/vista-banner.jpg\" alt=\"My Accounts: pending approvals surfaced above the fold, then accounts grouped by type with balances shown in local currency\" loading=\"lazy\" width=\"1600\" height=\"900\"><figcaption>My Accounts: pending approvals surfaced above the fold, then accounts grouped by type with balances shown in local currency</figcaption></figure><figure><img src=\"/projects/vista-screens.jpg\" alt=\"Marketing and product screens together \u2014 the campaign framing of the app alongside account filtering, custom views, pending bulk and single payment requests, and net worth summaries\" loading=\"lazy\" width=\"1200\" height=\"2133\"><figcaption>Marketing and product screens together \u2014 the campaign framing of the app alongside account filtering, custom views, pending bulk and single payment requests, and net worth summaries</figcaption></figure></div><section class=\"case-section\"><h2>What changed</h2><div><p>A digital banking product that treats multi-entity, multi-currency, multi-market operation as the normal case rather than an edge case \u2014 with approvals designed as core workflow, account views that scale to real portfolios, and one design system serving four localised subsidiaries across Gambia, Guinea, Sierra Leone and Burkina Faso. The work was recognised with ITSS&#x27;s Most Outstanding Intern of the Year award for contributions to Vista.</p></div></section><section class=\"case-section\"><h2>The evidence</h2><div><p>The work was recognised with ITSS&#x27;s Most Outstanding Intern of the Year award, and the letter names the Vista Bank project UI/UX design specifically as what it was awarded for \u2014 client-side recognition tied to this project rather than a general commendation, readable in full on the credentials page. The design shipped across four localised subsidiaries on a single system, with entity, currency and language handled as first-class context rather than as settings.</p></div></section><section class=\"case-section\"><h2>What I\u2019d test next</h2><div><p>The entity switcher carries the most risk in the product, because acting in the wrong entity means moving the wrong company&#x27;s money. I would test whether mandate holders can tell at a glance which entity they are operating in before they initiate a transfer, and whether the approval counts read as work assigned to them rather than as notifications they can dismiss. That needs real corporate customers rather than internal reviewers.</p></div></section><p style=\"margin-top:40px\"><a class=\"button primary\" href=\"https://vistabankgroup.com/group/about/\" target=\"_blank\" rel=\"noopener\">View vistabankgroup.com \u2197</a></p></div>", "kremor-ai": "<p class=\"drawer-kicker\">Live product</p><h2 id=\"preview-title\">Kremor AI</h2><p class=\"drawer-intro\">African textiles as a design language, not a print \u2014 a generator, a storefront, and the workshop floor that turns a prompt into a garment.</p><dl class=\"drawer-facts\"><div><dt>MY ROLE</dt><dd>UI/UX Designer \u2014 Design &amp; Research Lead, Kremor AI (contract, part-time)</dd></div><div><dt>WHEN</dt><dd>June 2024 \u2013 July 2026</dd></div><div><dt>FOCUS</dt><dd>Generative product UX, role-based operations, prompt-to-garment workflow</dd></div></dl><img class=\"archive-cover\" src=\"/projects/kremor-hero.jpg\" alt=\"Kremor AI interface overview\" width=\"2000\" height=\"1390\"><div class=\"archive-story\"><section class=\"case-section\"><h2>The short version</h2><div><p>Kremor AI is a fashion-technology platform that generates custom African clothing from a prompt and then has it made. It runs as three connected surfaces: a storefront selling AI-generated Ankara womenswear, menswear and bags; a creative workspace where a design is explored and iterated; and an admin platform where measurements, artisans, design approvals and production are managed by role. I designed all three end to end on contract from June 2024 to July 2026 \u2014 flows, interface design, AI interaction patterns and the design system \u2014 and evaluated 96+ complex AI interaction tasks to find the patterns worth keeping.</p></div></section><section class=\"case-section\"><h2>What I owned</h2><div><p>I led the product design and the research on Kremor AI. I designed all three surfaces end to end: the storefront selling AI-generated Ankara womenswear, menswear and bags; the generative workspace where a design is explored and iterated; and the role-based admin platform covering orders, measurements, artisans, design approvals, production, messages, inventory, permissions and audit history. Separately from the product design, I worked on AI model evaluation for the platform \u2014 forensic benchmarking, dataset annotation and qualitative evaluation of LLM and generative-image output, including 96+ complex AI interaction tasks.</p></div></section><div class=\"metric-row\"><div><strong>3</strong><p>Connected surfaces \u2014 storefront, AI workspace, operations platform</p><small>Project scope</small></div><div><strong>5</strong><p>Operational roles in the permissions matrix</p><small>Project scope \u00b7 Super Admin, Design Manager, Production Manager, Support Agent, Inventory Manager</small></div><div><strong>96+</strong><p>Complex AI interaction tasks evaluated</p><small>Project scope \u00b7 AI evaluation work, distinct from the product design</small></div></div><section class=\"case-section\"><h2>The challenge</h2><div><p>African fashion is usually flattened twice over. Globally it is reduced to a single decorative idea \u2014 African print \u2014 when Ankara, Aso-Oke, Adire and Kente are distinct traditions with their own rules. And in most AI tools it would be flattened again, into a style filter applied to a Western silhouette. The brief was the opposite of that: use AI to widen what someone can imagine wearing, while treating the textiles as a language rather than a texture. That created two problems. Most people cannot describe a garment they have not seen, so a blank prompt box would fail exactly the person the product exists for. And a generated image is not a dress \u2014 someone still has to take measurements, approve a design, cut fabric and sew it, which meant the creative surface was worthless unless the workshop behind it was designed with the same care.</p></div></section><section class=\"case-section\"><h2>The tricky part</h2><div><p>Two forces pulled against each other. A generative tool is only useful to someone who can describe what they want, and the people this product exists for often cannot \u2014 they have an occasion, a feeling, a fabric they have seen somewhere, and no vocabulary for any of it. The blank prompt box is the honest interface for a generator and the wrong interface for this audience, so scaffolding had to be added without narrowing what someone is allowed to ask for. The harder constraint is physical: a generated image is not a dress. Somebody still takes measurements, approves the design, cuts fabric and sews it, which made the creative surface worthless unless the workshop behind it was designed with equal care \u2014 and that workshop involves five roles, genuinely dangerous actions like suspending an artisan or refunding a payment, and a need to reconstruct afterwards who did what.</p></div></section><section class=\"case-section\"><h2>Research &amp; learning</h2><div><p>Exploratory, product-design-led, with model-evaluation work alongside</p><p>Whether a blank prompt field could serve an audience that has an occasion and a feeling but no design language \u2014 and what has to exist operationally for a generated image to become a garment.</p><p>The honest interface for a generator is the wrong interface for this audience; and the creative surface is worthless without the workshop behind it.</p><p>Quick actions and phrased openers replaced the bare prompt box, and the operations platform was designed with equal care to the storefront, with dangerous actions gated and an immutable audit trail.</p><p>Whether the five designed roles match the roles the workshop actually runs on.</p></div></section><section class=\"case-section\"><h2>Design decisions</h2><div><ol><li>Named the textiles rather than the continent. The product speaks in Ankara, Aso-Oke, Adire, Kente and Afro-fusion instead of African print, because specificity is both the respect the subject is owed and the vocabulary the generator needs to work with.</li><li>Refused the blank prompt box. The assistant opens with quick actions \u2014 generate design concepts, show style options, explore trends, create layout variations for Ankara patterns \u2014 and the home page offers openers phrased how people actually talk: I want an African vibe wear for an event. Someone with a feeling but no vocabulary still gets a first move.</li><li>Sequenced the promise the way creative confidence is built: personalised designs takes what you already know about yourself, AI-powered creativity opens options you had not considered, and unique and exclusive returns ownership of the result to you. Input, exploration, authorship \u2014 in that order.</li><li>Kept the assistant present across the whole storefront rather than parking it in a separate tool, so browsing and creating stay one activity and inspiration can be acted on where it strikes.</li><li>Designed the Workspace around iteration rather than one-shot generation. A single field \u2014 ask anything, create anything \u2014 accepts reference material and voice, and History and Marketplace sit in the top bar, so a train of thought can be resumed instead of restarted. Creative process only compounds if it persists.</li><li>Anchored the generated in the physical. Product pages state fabric, care, delivery and how this was made, so the sustainability claim is carried by facts about the garment instead of a banner over the top of it.</li><li>Designed the pipeline from prompt to finished piece as one path \u2014 orders, measurements, artisans, design approval, production board, messages, exports \u2014 so a generated design has a documented route to a tailor&#x27;s hands, and craftsmanship stays in the loop rather than being replaced by the model.</li><li>Made the operating model explicit in a permissions matrix. Super Admin, Design Manager, Production Manager, Support Agent and Inventory Manager are laid against every action, with dangerous ones \u2014 suspend an artisan, cancel an order, refund a payment, override a status \u2014 marked and confirmation-gated, and always-allowed permissions shown as locked rather than quietly missing.</li><li>Made accountability legible with an immutable, read-only audit log where every entry is timestamped and attributed to the role that acted, human or system \u2014 necessary in a product where a model, an agent and a manager all touch the same order.</li><li>Designed staff changes around the customer, not the employee record. Suspending a support agent surfaces their twelve open conversations before anything else and offers reassignment \u2014 automatically by workload and availability, or by hand with each agent&#x27;s active count and workload visible, and a preview of the conversation being moved.</li><li>Maintained the design system across all three surfaces \u2014 shared text and colour styles, a component page, and a Ready for Dev page \u2014 so the storefront, the workspace and the admin platform read as one product and engineering had a single source to build from.</li></ol></div></section><div class=\"case-gallery\"><figure><img src=\"/projects/kremor-mobile.jpg\" alt=\"The mobile system end to end \u2014 the design assistant with its quick actions, the generative home page, shop filtered by Ankara womenswear, menswear and bags, the product detail with size, colour, fabric and how the piece was made, About, contact, login and account creation\" loading=\"lazy\" width=\"1612\" height=\"1892\"><figcaption>The mobile system end to end \u2014 the design assistant with its quick actions, the generative home page, shop filtered by Ankara womenswear, menswear and bags, the product detail with size, colour, fabric and how the piece was made, About, contact, login and account creation</figcaption></figure><figure><img src=\"/projects/kremor-workspace.jpg\" alt=\"Kremor.AI Workspace: one prompt field reading ask anything, create anything, with attachment and voice input, a generate action, and Marketplace and History in the top bar \u2014 so a session of creative work can be returned to rather than restarted\" loading=\"lazy\" width=\"1900\" height=\"1844\"><figcaption>Kremor.AI Workspace: one prompt field reading ask anything, create anything, with attachment and voice input, a generate action, and Marketplace and History in the top bar \u2014 so a session of creative work can be returned to rather than restarted</figcaption></figure><figure><img src=\"/projects/kremor-phone.jpg\" alt=\"The storefront on a phone \u2014 the hero states the proposition in one line: African fashion designed by AI, sustainable, and rooted in heritage rather than borrowing from it\" loading=\"lazy\" width=\"1400\" height=\"1867\"><figcaption>The storefront on a phone \u2014 the hero states the proposition in one line: African fashion designed by AI, sustainable, and rooted in heritage rather than borrowing from it</figcaption></figure><figure><img src=\"/projects/kremor-admin.jpg\" alt=\"The accountability layer: an immutable audit log where every action is attributed to the role that took it, and a permissions matrix across Super Admin, Design Manager, Production Manager, Support Agent and Inventory Manager \u2014 with dangerous actions marked and locked permissions shown as locked\" loading=\"lazy\" width=\"2200\" height=\"1396\"><figcaption>The accountability layer: an immutable audit log where every action is attributed to the role that took it, and a permissions matrix across Super Admin, Design Manager, Production Manager, Support Agent and Inventory Manager \u2014 with dangerous actions marked and locked permissions shown as locked</figcaption></figure><figure><img src=\"/projects/kremor-staffing.jpg\" alt=\"Reassigning work when a support agent is suspended: the modal raises their twelve open conversations first, then offers auto-distribution by workload or manual selection, with each agent&#x27;s active conversation count and workload level visible before you choose\" loading=\"lazy\" width=\"2284\" height=\"944\"><figcaption>Reassigning work when a support agent is suspended: the modal raises their twelve open conversations first, then offers auto-distribution by workload or manual selection, with each agent&#x27;s active conversation count and workload level visible before you choose</figcaption></figure><figure><img src=\"/projects/kremor-figma.jpg\" alt=\"The admin dashboard laid out in the working Figma file \u2014 orders, measurements, artisans, design approvals, production board, messages and exports as one continuous pipeline, alongside the Ready for Dev and component pages\" loading=\"lazy\" width=\"2000\" height=\"1269\"><figcaption>The admin dashboard laid out in the working Figma file \u2014 orders, measurements, artisans, design approvals, production board, messages and exports as one continuous pipeline, alongside the Ready for Dev and component pages</figcaption></figure></div><section class=\"case-section\"><h2>What changed</h2><div><p>One product across three surfaces that each answer a different question: can I imagine it, can I buy it, can it actually be made. The generative side is scaffolded so that people who cannot yet describe what they want still get somewhere, the commerce side grounds AI output in fabric, care and provenance, and the operations side carries a role model, a permissions matrix and an immutable audit trail sturdy enough for real orders passing between managers, support agents and artisans. All three share one design system and a documented development handoff.</p></div></section><section class=\"case-section\"><h2>The evidence</h2><div><p>Kremor AI&#x27;s founder has written a reference describing the dual role \u2014 UI/UX design alongside AI model evaluation covering forensic benchmarking, dataset annotation and qualitative evaluation of LLM and generative image output \u2014 readable in full on the credentials page. 96+ complex AI interaction tasks were assessed to identify usability patterns, and the build is live. Three surfaces ship on one design system, with a Ready for Dev page marking exactly what engineering was handed.</p></div></section><section class=\"case-section\"><h2>What I\u2019d test next</h2><div><p>I would test the prompt scaffolding with people who have no design vocabulary and no familiarity with the textiles, because that is the audience the product is built for and the one most likely to stall at the first screen. On the operations side, I would want to know whether the permissions matrix matches how the workshop actually runs \u2014 whether the roles as designed correspond to the roles people really hold \u2014 before treating that model as settled.</p></div></section><p style=\"margin-top:40px\"><a class=\"button primary\" href=\"https://kremor-ai-clone.vercel.app/\" target=\"_blank\" rel=\"noopener\">View the live site \u2197</a></p></div>"};projects.forEach(p=>{if(featuredDetails[p.id])p.content=featuredDetails[p.id]});const drawer=document.querySelector('.project-drawer');let opener;let oldOverflow='';
function close(){drawer.close()}
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const p=projects.find(p=>p.id===button.dataset.project);opener=button;
drawer.querySelector('.drawer-content').innerHTML=p.content||`<p class="drawer-kicker">${p.category}</p><h2 id="preview-title">${p.name}</h2><p class="drawer-intro">${p.intro}</p><dl class="drawer-facts"><div><dt>My role</dt><dd>${p.role}</dd></div><div><dt>Timeline</dt><dd>${p.date}</dd></div></dl><figure class="drawer-image"><img src="/projects/${p.original}" alt="Original ${p.name} project presentation"><figcaption>From the original project portfolio</figcaption></figure><h3>What I did</h3><ul>${p.items.map(i=>`<li>${i}</li>`).join('')}</ul><h3>Scope & delivery</h3><p>${p.scope}</p><p>${p.result}</p><div class="drawer-links"><a class="button primary" href="/work/${p.id}/">Full case study ↗</a><a class="button" href="${p.url}" target="_blank" rel="noopener noreferrer">${p.label} ↗</a></div>`;
oldOverflow=document.body.style.overflow;document.body.style.overflow='hidden';drawer.showModal();drawer.scrollTop=0;drawer.querySelector('.drawer-close').focus();}));
drawer.querySelector('.drawer-close').addEventListener('click',close);drawer.addEventListener('click',e=>{if(e.target===drawer){const r=drawer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});drawer.addEventListener('close',()=>{document.body.style.overflow=oldOverflow;opener?.focus()});})();
